INSERT INTO `messages` VALUES (1,'ses_2d45e9f0abe345f2a018ed3d42ade9be','user','给我推荐几个优秀的报告','text','req_ea64da2d54084bfaafd63e4fa3e07d81',NULL,'recommendation','2026-08-17 06:38:53'),(2,'ses_2d45e9f0abe345f2a018ed3d42ade9be','assistant','未限定条件，已按报告数据完整度推荐3份优秀案例。','recommendations','req_ea64da2d54084bfaafd63e4fa3e07d81','{\"request_id\": \"req_ea64da2d54084bfaafd63e4fa3e07d81\", \"session_id\": \"ses_2d45e9f0abe345f2a018ed3d42ade9be\", \"intent\": \"recommendation\", \"status\": \"recommendations\", \"assistant_message\": \"未限定条件，已按报告数据完整度推荐3份优秀案例。\", \"collected_tags\": [], \"information_incomplete\": true, \"question\": null, \"recommendations\": [{\"report_id\": \"rpt_9fe2f26e67e154787136ecd0\", \"report_name\": \"北京分行冯润蓬科创001号授信业务调查报告（科技型企业）\", \"report_type\": \"授信业务调查报告（科技型企业）\", \"score\": 93.0, \"recommendation_reason\": \"未限定条件，按报告标签与综述数据完整度推荐。\", \"matched_tags\": [], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"信息传输、软件和信息技术服务业>软件和信息技术服务业>软件开发\"}, {\"name\": \"企业规模\", \"value\": \"部分（员工334人，营收5亿以上，总资产5亿以上，未明确划型口径）\"}, {\"name\": \"主营业务\", \"value\": \"技术开发及互联网信息服务，通过短视频进行智能营销推广客户产品，提供一站式KOL资源采买服务、社交大数据服务、社媒传播策略服务\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"人民币5亿元以上（2026年3月末合并口径）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"人民币5亿元以上（2026年3月末合并口径）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"人民币100万元至500万元（2026年3月合并口径未经审计）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"人民币1亿元至5亿元（2026年3月合并口径未经审计）\"}, {\"name\": \"是否集团客户\", \"value\": \"否\"}, {\"name\": \"是否科技型企业\", \"value\": \"是\"}, {\"name\": \"所有制性质\", \"value\": \"股份有限公司（民营控股，实控人为自然人******）\"}, {\"name\": \"授信金额\", \"value\": \"综合授信额度人民币1000万元至5000万元，敞口额度1000万元至5000万元\"}, {\"name\": \"授信期限\", \"value\": \"1年\"}, {\"name\": \"授信品种\", \"value\": \"综合授信（含流动资金贷款、银行承兑汇票、国内信用证）\"}, {\"name\": \"担保方式\", \"value\": \"信用\"}, {\"name\": \"担保人\", \"value\": \"无担保人\"}, {\"name\": \"担保物\", \"value\": \"无抵质押物\"}, {\"name\": \"贷款用途\", \"value\": \"用于申请人日常经营使用，包含子公司垫资储值支付KOL达人采购等服务费\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为其自身正常经营收入（主要为品牌广告回款）\"}, {\"name\": \"申请性质\", \"value\": \"续借（原额度续借）\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"北京分行冯润蓬科创001号授信业务调查报告（科技型企业）\", \"报告类型\": \"授信业务调查报告（科技型企业）\", \"客户概况\": \"申请人成立于2009年，股份有限公司，注册资本与实收资本未披露；信用等级BBB；所属行业为软件开发。实际控制人为法定代表人、董事长兼总经理徐志斌，控股股东合计持股16.7753%。属于国家级高新技术企业、专精特新中小企业，已完成E轮私募融资，股权结构稳定。\", \"主营业务与经营\": \"主营一站式KOL资源采买及AI短视频营销服务，覆盖抖音、小红书等平台，客户包括华为、雅诗兰黛等知名品牌。经营模式为先预付媒体平台费用采购达人资源，后收取下游广告主回款，账期错配明显。2025年撮合交易规模约5亿以上，处于KOL投放平台第一阵营。\", \"财务概况\": \"2025年合并营收5亿以上，净利润1000万-5000万，毛利率14%；截至2026年3月总资产5亿以上，净资产1亿-5亿，资产负债率60%-70%，有息负债1亿-5亿均为短期借款。应收账款周转天数155天，经营性现金流净流出。报告未披露2026年完整年度财务数据。\", \"授信方案\": \"本次申请原额度续借，综合授信人民币1000万-5000万（非承敞口），期限1年，品种包括银行承兑汇票、流动资金贷款、国内信用证，用于日常经营周转。较上轮增加敞口额度500万-1000万。\", \"担保与还款\": \"担保方式为信用，无保证人、无抵质押物。还款来源主要依靠自身正常经营收入，近三年营业收入均超5亿以上，预计2026年维持同等水平。\", \"主要风险\": [\"经营现金流持续为负：2024年和2025年经营活动净现金流分别为-7095万元和-5407万元，资金周转依赖外部融资，存在流动性压力。\", \"应收账款回收风险：应收账款周转天数逐年延长至155天，虽客户质量较高但回款周期长且集中度高，若大客户延迟付款将影响偿债能力。\", \"前次审批条件中‘用信后6个月内合同回款账户覆盖率>100%’未达成，反映贷后管理执行不到位。\"], \"综合评价\": \"申请人作为互联网红人经济赛道头部服务商，技术积累深厚、客户优质且盈利稳健增长，但面临行业竞争加剧、经营现金流连续两年净流出的挑战。本次续借金额较小且为信用方式，需重点关注应收款回笼和现金流转正情况。\"}}, {\"report_id\": \"rpt_56310d862ec36b2a81581a11\", \"report_name\": \"同驭汽车综合金融服务方案及授信业务调查报告\", \"report_type\": \"综合金融服务方案及授信业务调查报告\", \"score\": 93.0, \"recommendation_reason\": \"未限定条件，按报告标签与综述数据完整度推荐。\", \"matched_tags\": [], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"汽车线控底盘零部件行业（高阶自动驾驶核心赛道）\"}, {\"name\": \"企业规模\", \"value\": \"大型（结合员工人数未披露，但年营收1亿-5亿元区间，总资产1亿-5亿元区间，产能100万-500万套/年，且为国家级专精特新小巨人，推断为大型企业）\"}, {\"name\": \"主营业务\", \"value\": \"中国汽车智能底盘系统一级供应商，专注于新一代线控底盘关键技术的研发和产业化，产品布局涵盖线控制动、线控转向、线控悬架和底盘域控制器。已量产主力产品包括EHB线控液压制动系统等，正在测试的新品有EMB电子机械制动、SBW线控转向等。\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"1亿-5亿元人民币（合并报表口径，2025年9月末）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"5000万-1亿元人民币（合并报表口径，2025年9月末）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"-6533万元人民币（合并报表口径，2025年1-9月累计）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"-10543万元人民币（合并报表口径，2025年1-9月）\"}, {\"name\": \"是否集团客户\", \"value\": \"否\"}, {\"name\": \"是否科技型企业\", \"value\": \"是\"}, {\"name\": \"所有制性质\", \"value\": \"有限责任公司（港澳台投资、非独资），实际控制人为舒强，穿透后认定为民营控股\"}, {\"name\": \"授信金额\", \"value\": \"本次申请授信总额人民币5000万-1亿元，敞口5000万-1亿元\"}, {\"name\": \"授信期限\", \"value\": \"1年\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款\"}, {\"name\": \"担保方式\", \"value\": \"信用\"}, {\"name\": \"担保人\", \"value\": \"无\"}, {\"name\": \"担保物\", \"value\": \"无\"}, {\"name\": \"贷款用途\", \"value\": \"用于支付采购合同、办公地租金、员工工资等日常营运周转，具体为原材料采购、产线扩产、研发人员薪酬等\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为企业经营收入，补充还款来源为企业账面货币资金（含存款及短期理财）。2024年营收1亿-5亿，2025全年预计达1亿-5亿。\"}, {\"name\": \"申请性质\", \"value\": \"首贷（首次向我行申请授信）\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"同驭汽车综合金融服务方案及授信业务调查报告\", \"报告类型\": \"综合金融服务方案及授信业务调查报告\", \"客户概况\": \"公司2016年成立，注册资本******万元，实收资本******万元，港澳台投资非独资有限责任公司，实控人舒强。属汽车线控底盘零部件行业，国家级专精特新小巨人、高新技术企业。累计五轮股权融资超5亿元，股东含东风、小米、北汽等产业资本及多家金融机构。\", \"主营业务与经营\": \"主营智能底盘系统一级供应商，产品覆盖线控制动（EHB为主营收80%-90%以上）、转向、悬架和域控制器，全球极少数实现X-Y-Z三轴全栈布局的企业。量产客户包括零跑、北汽福田、江淮等80余家车企200余款车型，单一最大客户零跑占比50%-60%。上海嘉定、江西宜春两大基地+南京研发中心，年产100万-500万套线控制动产品。\", \"财务概况\": \"2022-2024年营业收入分别为1亿-5亿、1亿-5亿、1亿-5亿；毛利率逐年下降至9%-10%；净利润持续亏损，2024年净亏约18369万元（含哪吒汽车坏账损失8554万元）。截至2025年9月，资产总额1亿-5亿，资产负债率20%-30%，货币资金充裕但经营性现金流长期为负，主要依赖外部股权融资输血。\", \"授信方案\": \"首次申请我行人民币5000万-1亿一年期纯信用流动资金贷款，固定利率2%-3%。其中1000万-5000万为备用额度，启用条件为企业在我行存款及回款结算流水达标。资金用于原材料采购、产线扩产、研发薪酬等日常营运周转。\", \"担保与还款\": \"担保方式：信用。还款来源以经营收入为主（2024年营收1亿-5亿），账面货币资金作为补充还款来源。\", \"主要风险\": [\"公司连续多年亏损且亏损幅度扩大，盈利能力弱，未分配利润已转负，自身造血能力不足。\", \"经营活动现金流持续大额净流出，高度依赖外部股权融资维持运营，后续融资能力存不确定性。\", \"下游客户集中度较高，单一大客户零跑汽车营收占比50%-60%，曾因合众新能源应收账款违约产生重大坏账损失。\"], \"综合评价\": \"该公司属于国产线控底盘赛道头部科创企业，技术积累深厚、市场地位领先，获得多轮知名机构投资，负债率低、短期偿债能力强。但当前仍处于高投入成长期，盈利尚未改善、经营性现金流持续为负，对股权融资依赖度高，整体风险可控但仍需关注其商业化进展与外源融资持续性。\"}}, {\"report_id\": \"rpt_eed2215a19de9874d90ad46e\", \"report_name\": \"上海滴水湖商业旅游开发管理有限公司经营性物业贷款授信调查报告\", \"report_type\": \"综合金融服务方案及授信业务调查报告（适用于经营性物业贷款）\", \"score\": 89.5, \"recommendation_reason\": \"未限定条件，按报告标签与综述数据完整度推荐。\", \"matched_tags\": [], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"住宿和餐饮业-住宿业-旅游饭店-旅游饭店\"}, {\"name\": \"企业规模\", \"value\": \"中型企业\"}, {\"name\": \"主营业务\", \"value\": \"酒店投资与管理，旗下运营滴水湖洲际酒店等；兼营实业投资、会所管理、会展服务、游艇销售等。\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"不可提取（完全脱敏）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"部分（区间推算）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"-7878万元（2025年1-6月合并口径，未经审计）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"-276万元（2025年1-6月）\"}, {\"name\": \"是否集团客户\", \"value\": \"是\"}, {\"name\": \"是否科技型企业\", \"value\": \"否\"}, {\"name\": \"所有制性质\", \"value\": \"国有绝对控股\"}, {\"name\": \"授信金额\", \"value\": \"人民币5亿以上（增量额度5亿以上，增量后总敞口5亿以上）\"}, {\"name\": \"授信期限\", \"value\": \"15年\"}, {\"name\": \"授信品种\", \"value\": \"经营性物业贷款\"}, {\"name\": \"担保方式\", \"value\": \"保证担保+抵押担保\"}, {\"name\": \"担保人\", \"value\": \"港城集团（上海港城开发(集团)有限公司）提供连带责任保证担保\"}, {\"name\": \"担保物\", \"value\": \"浦东新区申港街道南岛路1号、环湖西一路6弄6号的酒店及配套设施（上海滴水湖洲际酒店），评估价值5亿以上，抵押率60%-70%\"}, {\"name\": \"贷款用途\", \"value\": \"置换存量经营性物业贷款、项目贷款，置换股东及关联方借款，支付某重点项目款及日常运营支出\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源：滴水湖洲际酒店及配套会议中心、南岛2号的经营收入；补充还款来源：集团统筹与股东资金支持\"}, {\"name\": \"申请性质\", \"value\": \"增贷，增量额度5亿以上\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"上海滴水湖商业旅游开发管理有限公司经营性物业贷款授信调查报告\", \"报告类型\": \"综合金融服务方案及授信业务调查报告（适用于经营性物业贷款）\", \"客户概况\": \"客户为港城集团全资子公司，国有绝对控股，属住宿和餐饮业-旅游饭店。旗下运营滴水湖洲际酒店、斯南格尔精选酒店等多家高端酒店及游艇俱乐部，其中洲际酒店为区域地标。成立于2007年8月，注册资本5亿以上，实收资本5亿以上，由浦东新区国资委穿透控制。信用等级BBB(2025年4月)。\", \"主营业务与经营\": \"主营酒店投资与经营管理，委托洲际集团负责日常运营。核心资产为滴水湖洲际酒店（五星级标准，280间客房），收入以客房为主（约占50%-60%），辅以餐饮、宴会及其他服务。2023年上半年完成品牌翻牌升级后全面开放营业，2024年为首个完整经营年度，入住率约50%-60%。\", \"财务概况\": \"合并口径：2022-2024年主营业务收入分别为1000万-5000万、1亿-5亿、1亿-5亿，逐年提升；但持续亏损，净利润分别为-31,184万元、-26,011万元、-16,602万元（2024年含报废损失5000万-1亿）。资产负债率高企（2024年90%-100%），流动比率极低（<1%），经营活动现金流净额2024年为负（-2866万元）。货币资金5000万-1亿。报告未披露最新净资产具体数值。\", \"授信方案\": \"申请增贷：新增经营性物业贷款额度5亿元以上，期限15年，利率五年期LPR。用途包括置换存量经营性物业/项目贷款、股东借款、重点项目款及日常运营支出。本次增量敞口5亿以上，总授信敞口增至5亿以上。\", \"担保与还款\": \"担保方式为保证+抵押：①保证人港城集团提供连带责任保证（AA-评级）；②以名下滴水湖洲际酒店及配套设施（评估价值5亿以上，抵押率60%-70%）作抵押。第一还款来源为酒店经营收入，补充还款来源为集团统筹与股东支持。签订资金监管协议，全部营收归集我行账户封闭管理。\", \"主要风险\": [\"财务风险突出：连续三年大额亏损，未分配利润累计超-5亿，资产负债率远高于行业均值（2024年90%-100%），短期偿债指标弱（现金比率9%-10%，一年内到期有息负债保障倍数仅0.68倍），且最近一期经营活动现金流由正转负。\", \"前5年还款计划不达标：按测算前5年归还比例仅6%-7%，低于管理办法要求的30%最低比例，依赖股东外部流动性支持维持还本付息。\", \"信息缺口：报告中多项关键数据脱敏或缺失（如申请人最新净资产、近三年精确营业收入及成本、贷款利率加点区间S的具体值、RAROC结果均未明确披露），影响独立判断。\"], \"综合评价\": \"客户依托国资背景及稀缺区位酒店资产，经营呈恢复态势，但自身盈利能力差、杠杆高、现金流紧张，对股东支持高度依赖。授信方案中还款计划明显弱于政策要求，需重点关注后续入住率提升及股东实际履约能力。整体属于强担保覆盖下的高风险融资安排。\"}}], \"statistic\": null, \"answer\": null}','recommendation','2026-08-17 06:38:53'),(3,'ses_c3c504aa9d9d499c96f82ca7c61ae270','user','筛选制造业小微企业报告','text','req_2f878f2873b042f58d3d990e4a58f99f',NULL,'filter','2026-08-17 07:07:48'),(4,'ses_c3c504aa9d9d499c96f82ca7c61ae270','assistant','已按全部 2 个条件筛选到 21 份报告。','filter_results','req_2f878f2873b042f58d3d990e4a58f99f','{\"request_id\": \"req_2f878f2873b042f58d3d990e4a58f99f\", \"session_id\": \"ses_c3c504aa9d9d499c96f82ca7c61ae270\", \"intent\": \"filter\", \"status\": \"filter_results\", \"assistant_message\": \"已按全部 2 个条件筛选到 21 份报告。\", \"collected_tags\": [{\"name\": \"企业规模\", \"value\": \"小微企业\", \"dimension\": \"客户维度\", \"confidence\": 1.0}, {\"name\": \"行业分类\", \"value\": \"制造业\", \"dimension\": \"客户维度\", \"confidence\": 1.0}], \"information_incomplete\": true, \"question\": null, \"recommendations\": [{\"report_id\": \"rpt_7d325f6d6faafb235bc1eb63\", \"report_name\": \"杭州分行-332185-徐欣湉-普惠-001_已脱敏_202607141930.docx\", \"report_type\": \"综合金融服务方案及授信送审报告\", \"score\": 100.0, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小微企业\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业\", \"similarity\": 1.0}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业\"}, {\"name\": \"企业规模\", \"value\": \"小微企业\"}, {\"name\": \"主营业务\", \"value\": \"蜂产品加工与销售，主营鲜蜂皇浆、蜂皇浆干粉、水溶性冻干粉、蜂胎冻干粉、雄蜂蛹冻干粉、蜂蜜、蜂花粉、蜂胶等蜂类保健品，内销超市连锁，出口日韩、东南亚、欧美\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"1000万-5000万元（2025年）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"不可提取（仅披露资产负债率50%-60%，无直接总负债数值或区间）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"100万-500万元（2025年）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（报告中未见经营活动现金流量净额数据）\"}, {\"name\": \"是否集团客户\", \"value\": \"否\"}, {\"name\": \"是否科技型企业\", \"value\": \"是\"}, {\"name\": \"所有制性质\", \"value\": \"民营/私人控股\"}, {\"name\": \"授信金额\", \"value\": \"本次申请流动资金贷款100万-500万，敞口100万-500万\"}, {\"name\": \"授信期限\", \"value\": \"12个月（1年）\"}, {\"name\": \"授信品种\", \"value\": \"企业流动资金贷款（科创普惠流动资金贷），同时涉及固定资产技改贷与知识产权质押融资作为配套方案\"}, {\"name\": \"担保方式\", \"value\": \"保证+抵押组合：追加实控人夫妇连带责任保证 + 杭州供销农信担保提供80%连带责任保证（优质类融资性担保机构）；另拟用工业厂房抵押用于固定资产技改贷\"}, {\"name\": \"担保人\", \"value\": \"实控人夫妇（全额连带责任保证）+ 杭州供销农信担保有限公司（承担80%连带责任保证）\"}, {\"name\": \"担保物\", \"value\": \"企业自有工业厂房（用于固定资产技改贷）；知识产权：2项发明专利、22项实用新型专利质押（用于知识产权质押融资）\"}, {\"name\": \"贷款用途\", \"value\": \"置换我行存量贷款（无还本续贷），原合同编号183250005（SB）的《小企业流动资金借款合同》项下贷款本金；同时可用于采购原材料（如蜂产品原料）\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为企业营业收入（近三年稳定，营业现金流能覆盖）；第二还款来源为保证人代偿能力（实控人夫妇及担保公司）\"}, {\"name\": \"申请性质\", \"value\": \"存量续借（无还本续贷），不增加敞口\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"杭州分行-332185-徐欣湉-普惠-001_已脱敏_202607141930.docx\", \"报告类型\": \"综合金融服务方案及授信送审报告\", \"客户概况\": \"客户成立于2006年12月，注册地杭州桐庐，实控人持股70%-80%，为省级专精特新、国家级高新技术企业、科技型中小企业。主营蜂制品加工，员工25人，研发人员占比40%-50%。内销覆盖连锁商超，出口日韩、东南亚、欧美，出口占比30%-40%。征信无逾期涉诉，与我行有存量合作100万-500万元。资产含厂房、商铺、多套住宅可抵押。\", \"主营业务与经营\": \"主营业务为蜂皇浆、蜂胶、蜂蜜等蜂产品加工销售，自有GMP产线、冷库和检测中心，拥有22项实用新型专利和2项发明专利。2023-2025年营业收入分别为2587万元、2602万元、1000万-5000万元，经营稳定；毛利率约14%且连续增长，主要因新品高端化。下游前五大客户中一家占40%-50%；上游主要为养蜂合作社。纳税申报收入与报表收入存在差距（相差500万-1000万），解释为企业避税行为。\", \"财务概况\": \"近三年总资产均在1000万-5000万元区间，净资产1000万-5000万元；资产负债率在50%-60%之间，流动比率90%-100%（2025年）；存货802万元占流动资产比重较高；应收账款周转天数上升至86天左右；货币资金100万-500万元；净利润每年100万-500万元；现金流未明确披露。财报均未经审计，但以流水佐证收入可信度尚可。短期借款集中，一年内到期有息负债保障倍数小于1（0.09倍）。\", \"授信方案\": \"本次申请流动资金贷款100万-500万元，期限1年，单笔提款不超过1年，用途为置换我行原有贷款（无还本续贷），不新增流贷需求。支付方式为受托支付。属存量续借性质。内部评级bbb。\", \"担保与还款\": \"担保方式：由优质融资性担保机构提供80%连带责任保证，并追加实控人夫妇全额连带责任保证。还款来源为主要来自企业经营收入（近年营收稳定1000万-5000万元，净利润100万-500万元），同时通过回款专户闭环管控。另有知识产权质押作为补充增信措施。\", \"主要风险\": [\"财务数据均为未审计数，销售收入区间跨度大（1000万-5000万元），精确金额不明，影响对偿债能力的准确判断。\", \"短期债务集中，流动负债占比高，一年内有息负债保障倍数仅0.09倍，现金较少，短期偿付压力较大。\", \"纳税申报收入与企业报表收入差异达500万-1000万元，存在税务合规风险且可能反映真实盈利能力偏离报表。\"], \"综合评价\": \"该客户经营历史较长，技术资质较好，主业稳定，具有一定市场地位；但财务信息精度有限，短期流动性偏紧，对外部融资依赖度高。本次授信为无还本续贷，不增加敞口，且有国有担保公司和实控人双重保证，整体信用风险可控。\"}}, {\"report_id\": \"rpt_64efc1553b56ef09c89a27f6\", \"report_name\": \"温州分行-王悦-普惠科创授信送审意见书（2024年试行版）\", \"report_type\": \"上海银行送审意见书（2024年试行版，适用于一般业务、普惠科创业务）\", \"score\": 100.0, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小微企业（从业人员20人，营收区间1000万-5000万，总资产区间1000万-5000万，符合工信部中小微划型标准；报告未明确社会认定但依据指标判断为小微）\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业\", \"similarity\": 1.0}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业\"}, {\"name\": \"企业规模\", \"value\": \"小微企业（从业人员20人，营收区间1000万-5000万，总资产区间1000万-5000万，符合工信部中小微划型标准；报告未明确社会认定但依据指标判断为小微）\"}, {\"name\": \"主营业务\", \"value\": \"研发、生产、销售电子元器件，主要产品为各类高压真空灭弧室配件，应用于高压电气领域、新能源充电桩、人工智能领域。\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"截至2025年10月末，公司总资产1000万-5000万元。\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"截至2025年10月末，公司总负债500万-1000万元。\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"无法提取（损益表仅列示百分比变化，未给出具体金额）。\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（全文未提供现金流量表数据）。\"}, {\"name\": \"是否集团客户\", \"value\": \"否\"}, {\"name\": \"是否科技型企业\", \"value\": \"是（省级专精特新企业，且拥有10项实用新型专利）。\"}, {\"name\": \"所有制性质\", \"value\": \"民营/私人控股（实控人******持股100%）\"}, {\"name\": \"授信金额\", \"value\": \"本次申请综合授信额度不超过人民币100万-500万元，敞口不超过人民币100万-500万元（其中流动资金贷款100万-500万，票据承兑额度100万-500万免保证金）。\"}, {\"name\": \"授信期限\", \"value\": \"不长于12个月（其中流动资金贷款单笔期限不长于12个月，票据承兑单笔业务期限不长于6个月）。\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款、银行承兑汇票\"}, {\"name\": \"担保方式\", \"value\": \"自然人保证（个人连带责任保证），由实控人******及配偶******提供个人全额连带责任保证。\"}, {\"name\": \"担保人\", \"value\": \"实控人******及其配偶******\"}, {\"name\": \"担保物\", \"value\": \"无抵押物或质押物，仅为信用保证。\"}, {\"name\": \"贷款用途\", \"value\": \"采购原材料、支付工资、置换他行贷款（乐清农商行等存量债务）。\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为企业经营收入（近三年及一期营收稳定，经营现金流较好）；第二还款来源为保证人的代偿能力。\"}, {\"name\": \"申请性质\", \"value\": \"首次申请\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"温州分行-王悦-普惠科创授信送审意见书（2024年试行版）\", \"报告类型\": \"上海银行送审意见书（2024年试行版，适用于一般业务、普惠科创业务）\", \"客户概况\": \"申请人为成立于2012年的制造业企业，注册及经营地址位于浙江省温州市乐清市，租赁工业厂房约5162.50平方米。注册资本未披露，法定代表人持股100%，为省级专精特新企业和国家级高新技术企业，从业人员20人，研发人员3人，拥有10项实用新型专利。实控人******，大专学历，从业13年，已婚。关联公司两家，均无负面信息。\", \"主营业务与经营\": \"主营业务为高压真空灭弧室配件的研发、生产与销售，产品应用于高压电气、新能源充电桩和人工智能领域。近三年产能利用率90%-100%，毛利率20%-30%。采购以铜材为主，结算方式现金或承兑；销售模式包括展会、转介绍和线下拜访，账期90-120天，下游客户含尼普顿电器等。在手订单量100万-500万个。行业竞争格局中属高端配件细分市场。\", \"财务概况\": \"报告显示财务数据未经审计。2022至2024年营业收入均为1000万-5000万元且呈增长趋势；毛利率分别为25.80%、21.04%和22.38%；费用率波动较大，2024年因财务费用增加导致利润总额下降。截至2025年10月末总资产1000万-5000万元，负债500万-1000万元，资产负债率20%-30%，流动比率约3.84，速动比率约2.53。应收账款周转天数150-200天，存货周转天数100-150天。纳税系统销售额低于报表营收，部分收入未开票未纳税。银行流水折合全年与报表匹配。征信报告显示融资余额500万-1000万元，五级分类正常。\", \"授信方案\": \"本次申请授信金额100万-500万元，敞口相同，期限12个月，品种为企业流动资金贷款/循环贷款，用途为采购原材料、支付工资及置换他行贷款，首次申请。利率不低于LPR减40个基点。\", \"担保与还款\": \"担保方式为自然人保证：实控人******及其配偶******提供个人全额连带责任保证。保证人主要资产为一辆奔驰车，无房产，对外担保情况未详细说明。还款来源为主要依靠企业经营现金流，近三年营收稳定且具有较强还款能力。\", \"主要风险\": [\"财务报表未经审计，关键科目如货币资金、应收账款、存货等具体数值仅列区间范围，精确度不足。\", \"原材料铜价受国际大宗商品影响波动频繁，可能直接影响生产成本和利润率；报告中提及2025年盈利下滑即与此相关。\", \"应收账款周转天数较长（150-200天），对流动性形成压力；下游客户集中度高，存在一定依赖风险。\", \"担保方式仅为个人信用保证，缺乏抵质押物增信措施，保障偏弱。\", \"实控人名下无房产，家庭资产有限，其对外担保余额较高（500万-1000万元），可能削弱代偿能力。\"], \"综合评价\": \"该企业成立十余年，主营高压真空灭弧室配件，属于国家鼓励的先进制造领域，具备专精特新资质和技术积累，近年营收持续增长但增速放缓，盈利能力受原材料价格挤压有所下滑。整体负债率较低，短期偿债指标尚可，但应收账款规模大、回款周期长，流动性管理需关注。本次授信方案基于存量合作基础提出，担保方式较弱，还款来源依赖于持续的经营现金流，综合来看业务具有一定经营性支撑，同时面临成本波动和应收积压的风险。\"}}, {\"report_id\": \"rpt_61404df740601d8943b42a9b\", \"report_name\": \"上海银行送审意见书（普惠及小企业业务模板）\", \"report_type\": \"普惠及小企业业务送审意见书（首贷）\", \"score\": 93.75, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小型企业\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"医药制造业（糖尿病并发症药物研发、生产与销售）\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"医药制造业（糖尿病并发症药物研发、生产与销售）\"}, {\"name\": \"企业规模\", \"value\": \"小型企业\"}, {\"name\": \"主营业务\", \"value\": \"糖尿病并发症药物的研发、生产与品牌运作；主要产品为硫辛酸胶囊和片剂等\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"5000万-1亿（2025年12月，合并报表口径）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"1000万-5000万（2025年12月，合并报表口径）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"不可提取（具体金额被脱敏或仅有比例区间）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（全文未披露该指标）\"}, {\"name\": \"是否集团客户\", \"value\": \"是，纳入******股份有限公司集团统一授信管理\"}, {\"name\": \"是否科技型企业\", \"value\": \"是国家高新技术企业\"}, {\"name\": \"所有制性质\", \"value\": \"有限责任公司（民营控股）\"}, {\"name\": \"授信金额\", \"value\": \"1000万-5000万元（流动资金贷款单户综合融资总量）\"}, {\"name\": \"授信期限\", \"value\": \"1年\"}, {\"name\": \"授信品种\", \"value\": \"企业流动资金贷款\"}, {\"name\": \"担保方式\", \"value\": \"母公司交易对手1保证（连带责任保证）\"}, {\"name\": \"担保人\", \"value\": \"母公司交易对手1（自然人，提供个人连带责任保证）\"}, {\"name\": \"担保物\", \"value\": \"无抵押质押物\"}, {\"name\": \"贷款用途\", \"value\": \"企业日常经营周转（补充流动资金用于市场推广费用及支付员工工资等）\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为企业经营活动产生的现金流；第二还款来源为保证人代偿\"}, {\"name\": \"申请性质\", \"value\": \"首贷\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"上海银行送审意见书（普惠及小企业业务模板）\", \"报告类型\": \"普惠及小企业业务送审意见书（首贷）\", \"客户概况\": \"******有限公司，2010年成立，有限责任公司，小型企业，主营糖尿病并发症药物的研发、生产与品牌运作，注册/实收资本4517万余元，实际控制人***。\", \"主营业务与经营\": \"主营业务为硫辛酸胶囊等糖尿病并发症药物，拥有49项专利；产品不进集采、不进医保，毛利率约85%，口服硫辛酸市场占有率70%-80%；前五大供应商集中度高，其中核心原料供应商1由股东关联方控股，成本优势明显。\", \"财务概况\": \"合并报表经审计，2023-2025年9月总资产持续增长，资产负债率从10%-20%降至5%-6%，毛利率稳定在80%-90%，净利润率从10%-20%升至30%-40%；单体报表未审计，无银行借款，销贷比为0；报告未披露具体金额。\", \"授信方案\": \"申请单户综合融资总量1000万-5000万元，全部为企业流动资金贷款，期限1年，用于日常经营周转，自主支付。\", \"担保与还款\": \"担保方式为母公司保证；还款来源主要依赖企业经营现金流。\", \"主要风险\": [\"公司营收60%-70%以上依赖于硫辛酸单品，产品结构单一，抗风险能力较弱。\", \"硫辛酸已纳入多地重点监控品种，未来被纳入全国集采概率较高，若集采落地将导致利润大幅下降。\", \"报告中财务数据均以区间形式呈现，缺乏精确数值，影响量化分析准确性。\"], \"综合评价\": \"该公司专注于糖尿病并发症蓝海赛道，技术壁垒高且盈利能力强，但存在产品高度集中和潜在政策集采风险；整体经营稳健，偿债能力尚可。\"}}, {\"report_id\": \"rpt_1c29133004e01429d0e333b0\", \"report_name\": \"上海银行送审意见书（普惠及小企业业务模板）-制氢设备客户续贷申请\", \"report_type\": \"授信送审意见书\", \"score\": 93.75, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小型企业\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业-电气机械和器材制造业-其他电气机械及器材制造-其他未列明电气机械及器材制造\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业-电气机械和器材制造业-其他电气机械及器材制造-其他未列明电气机械及器材制造\"}, {\"name\": \"企业规模\", \"value\": \"小型企业\"}, {\"name\": \"主营业务\", \"value\": \"制氢设备的制造和销售，包括高性能催化剂、双极板复合镀工艺、先进的极板结构及大功率耐波动电解水制氨系统等绿氢装备生产\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"1亿-5亿\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"1亿-5亿\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"100-500万元\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（全文未明确披露经营活动产生的现金流量净额）\"}, {\"name\": \"是否集团客户\", \"value\": \"是\"}, {\"name\": \"是否科技型企业\", \"value\": \"是\"}, {\"name\": \"所有制性质\", \"value\": \"私人绝对控股\"}, {\"name\": \"授信金额\", \"value\": \"500万-1000万元（敞口减少后）\"}, {\"name\": \"授信期限\", \"value\": \"1年\"}, {\"name\": \"授信品种\", \"value\": \"企业流动资金贷款\"}, {\"name\": \"担保方式\", \"value\": \"自然人保证（个人连带责任保证）+ 企业保证\"}, {\"name\": \"担保人\", \"value\": \"闫巍（实控人）、其配偶（姓名脱敏）、青骐骥科技（集团）有限公司\"}, {\"name\": \"担保物\", \"value\": \"不可提取（本笔授信仅采用保证方式，未设置抵押或质押物）\"}, {\"name\": \"贷款用途\", \"value\": \"归还******合伙企业（有限合伙）******\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为主营业务收入（制氢设备销售收入）；第二还款来源为担保人的代偿能力\"}, {\"name\": \"申请性质\", \"value\": \"续借（减少敞口）\"}, {\"name\": \"是否我行关联企业\", \"value\": \"不可提取（原文无明确勾选或陈述该字段）\"}], \"summary\": {\"报告名称\": \"上海银行送审意见书（普惠及小企业业务模板）-制氢设备客户续贷申请\", \"报告类型\": \"授信送审意见书\", \"客户概况\": \"申请人为******，私人绝对控股的小型企业，成立于2021年8月，注册资本1亿-5亿元，实收资本6066万元。所属行业为制造业中的其他未列明电气机械及器材制造。实际控制人闫巍，法定代表人段兴月。纳税等级B级，信用等级a。经营状态正常。报告未披露具体社保人数等最新数据。\", \"主营业务与经营\": \"主营制氢设备的制造和销售，产品包括碱性电解槽及核心材料（催化剂、双极板），拥有从零部件加工到系统装配的完整绿氢装备生产链。集团已获83项专利，产能满负荷可年产300台设备。下游客户主要为国企、央企及上市公司，收入主要来自电解槽销售。在手订单约1亿-5亿元，回款5000万-1亿元；整个集团所有订单合计5亿元以上。经营模式为产业链分工，子公司各司其职。\", \"财务概况\": \"截至2025年7月/9月：总资产1亿-5亿元，总负债1亿-5亿元，所有者权益1亿-5亿元，资产负债率50%-60%；流动比率0.92，速动比率0.64。2024年销售收入5000万-1亿元，毛利率20%-30%，净利润50-100万元，净利率1%-2%。2025年前三季度开票销售仅1000万-5000万元，但形成交付未开票收入约1000万-5000万元。现金流状况未明确披露。\", \"授信方案\": \"本次申请企业流动资金贷款500-1000万元，期限1年，用途为归还******合伙企业（有限合伙）借款。属续贷，敞口较前次减少500万-1000万元。支付方式未明确金额。\", \"担保与还款\": \"担保方式为自然人保证（实控人夫妻闫巍及其配偶******连带责任保证）以及一般保证人******青骐骥科技（集团）有限公司提供连带责任保证。还款来源为主营业务收入。第一还款来源被评价为充足。\", \"主要风险\": [\"申请人2025年前三季度开票收入仅1000万-5000万元，与上年度全年5000万-1亿元的营收差距较大，虽存在待验收确认收入，但仍反映出收入确认周期长、资金垫付压力大的风险。\", \"应收账款周转天数1042天、存货周转天数1647天，营运效率极低，资金占用严重，流动性偏紧（流动比率0.92）。\", \"短期借款余额5000万-1亿元，较上年大幅增加，且对外担保合计1000万-5000万元均为关联企业担保，或有负债风险较高。\"], \"综合评价\": \"该企业属于绿色制造领域，技术有一定领先性，订单增长较快，但财务数据显示运营效率低下、应收及存货周转缓慢，且前期研发投入大导致资金需求高。担保方为实控人夫妇及集团公司，有一定代偿能力。整体而言企业经营处于扩张期但伴随较大的流动性压力和回款不确定性。\"}}, {\"report_id\": \"rpt_ceda2df9b1a732d4a0b4b357\", \"report_name\": \"上电法兰管件有限公司综合金融服务方案及授信业务调查报告\", \"report_type\": \"综合金融服务方案及授信业务调查报告\", \"score\": 93.75, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小型企业\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业（金属制品业）\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业（金属制品业）\"}, {\"name\": \"企业规模\", \"value\": \"小型企业\"}, {\"name\": \"主营业务\", \"value\": \"不锈钢法兰、管件的制造和销售\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"5000万-1亿（2026年3月）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"1000万-5000万（2026年3月）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"100万-500万（2026年3月）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（无现金流量表）\"}, {\"name\": \"是否集团客户\", \"value\": \"否\"}, {\"name\": \"是否科技型企业\", \"value\": \"国家级高新技术企业、专精特新中小企业、科技型中小企业\"}, {\"name\": \"所有制性质\", \"value\": \"民营\"}, {\"name\": \"授信金额\", \"value\": \"本次申请授信额度不超过人民币1000万-5000万，其中敞口额度不超过人民币1000万-5000万\"}, {\"name\": \"授信期限\", \"value\": \"不长于1年\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款、资产池授信额度（可用于票据承兑）\"}, {\"name\": \"担保方式\", \"value\": \"实控人夫妇个人全额连带责任保证担保\"}, {\"name\": \"担保人\", \"value\": \"实控人******及其配偶******\"}, {\"name\": \"担保物\", \"value\": \"无抵押物或质押物\"}, {\"name\": \"贷款用途\", \"value\": \"用于支付货款、代发工资等日常经营周转\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源：申请人营业收入；第二还款来源：实控人夫妇担保视同信用\"}, {\"name\": \"申请性质\", \"value\": \"增量续贷\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"上电法兰管件有限公司综合金融服务方案及授信业务调查报告\", \"报告类型\": \"综合金融服务方案及授信业务调查报告\", \"客户概况\": \"申请人上电法兰管件有限公司成立于2017年，前身为温州市龙湾永兴上电法兰厂，注册资本和实收资本均未披露具体金额。企业为民营、国家级高新技术企业、专精特新中小企业，从事不锈钢法兰、管件的制造与销售，产品应用于石油、化工、冶金等行业。实际控制人持股100%。\", \"主营业务与经营\": \"主营业务为法兰和管件的生产销售，核心工艺为中频加热模锻成型，拥有数控立车等精密设备，具备特种设备压力管道元件制造资质。2025年起新增管件产线，设计产能提升至约2.5万吨/年（法兰2万吨+管件0.5万吨），当年产能利用率约65%（法兰）和40%（管件）。已切入英维克、高澜股份、海悟科技等液冷头部企业供应链，下游客户结构持续优化。原材料以青山控股集团的不锈钢为主，采购成本可控。\", \"财务概况\": \"报告仅提供了部分财务数据且未经审计：近三年营业收入均在1亿-5亿元区间，逐年增长；净利润从500万-1000万元增至1000万-5000万元；毛利率稳定在15%-16%，净利率维持在5%-6%左右。资产负债率20%-30%，流动比率大于200%，速动比率100%-150%。无现金流量表提供。纳税申报销售额远低于财务报表营收，主要原因为部分未开票收入未申报。有息债务合计1215万元（截至2025年末）。\", \"授信方案\": \"本次申请为增量续贷性质，总授信额度不超过人民币3000万元（敞口2400万元），期限不长于1年。品种包括流动资金贷款（单笔不超1年）和资产池授信额度（含票据承兑，信用加载率上限200%，单笔不超6个月）。用途为支付货款、代发工资等经营周转。\", \"担保与还款\": \"担保方式为由实控人及其配偶个人全额连带责任保证担保。第一还款来源为企业自身营业收入；第二还款来源为保证人视同信用代偿。保证人名下有房产估值约500万-1000万元，但已有抵押余额100万-500万元。\", \"主要风险\": [\"企业提供的财务报表未经审计，且存在大量未开票销售收入未进行税务申报的情况，财务信息真实性与完整性存疑。\", \"报告中多项关键财务数据（如营业收入、利润总额等）均以区间形式呈现（如\\\"1亿-5亿\\\"），而非精确数值，影响风险评估的准确性。\", \"企业无对外担保，但他行融资中部分担保方式为\\\"保证\\\"或\\\"信用\\\"，且他行授信条件可能优于我行，需关注同业竞争风险。\"], \"综合评价\": \"上电法兰是一家专注于法兰管件制造的民营高新企业，近年营收稳步增长，盈利水平处于行业合理区间。公司已完成搬迁扩产并进入液冷行业头部供应商体系，成长性较好。但财务信息披露不足（未经审计、缺失现金流表、关键指标用范围替代）、部分销售行为合规性存疑，以及面临低端市场竞争和原料价格波动等因素，构成主要制约因素。整体而言，企业经营基本面稳健，但信息缺口降低了可评估性和透明度。\"}}, {\"report_id\": \"rpt_1405d72b2f081201cf0a1381\", \"report_name\": \"中创达无还本续贷授信尽调报告（线下普惠贷款首贷业务）\", \"report_type\": \"授信业务尽职调查报告（线下普惠首贷/续贷）\", \"score\": 93.75, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小型或微型企业（员工14人，参保14人；营收500万-1000万区间）\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"专用设备制造业\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"专用设备制造业\"}, {\"name\": \"企业规模\", \"value\": \"小型或微型企业（员工14人，参保14人；营收500万-1000万区间）\"}, {\"name\": \"主营业务\", \"value\": \"工业炉窑行业节能环保燃烧设备的研发、制造和销售\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"200%以上（相对于实收资本等基数，具体数值因脱敏不可得）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"200%以上（相对于实收资本等基数，具体数值因脱敏不可得）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"-0.4万元（2026年3月累计）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（全文未找到可验证出处）\"}, {\"name\": \"是否集团客户\", \"value\": \"否\"}, {\"name\": \"是否科技型企业\", \"value\": \"是\"}, {\"name\": \"所有制性质\", \"value\": \"民营/私人控股\"}, {\"name\": \"授信金额\", \"value\": \"100万以下\"}, {\"name\": \"授信期限\", \"value\": \"一年\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款、银票贴现\"}, {\"name\": \"担保方式\", \"value\": \"保证担保（苏州高新中小企业融资担保有限公司对不低于本金80%-90%提供保证担保）+ 个人连带责任保证（实际控制人******）\"}, {\"name\": \"担保人\", \"value\": \"苏州高新中小企业融资担保有限公司、实际控制人******\"}, {\"name\": \"担保物\", \"value\": \"无抵押物或质押物\"}, {\"name\": \"贷款用途\", \"value\": \"无还本续贷\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为公司经营活动产生的现金流入；第二还款来源为担保方代偿\"}, {\"name\": \"申请性质\", \"value\": \"无还本续贷\"}, {\"name\": \"是否我行关联企业\", \"value\": \"不可提取（全文未出现\'关联企业\'字段且无明确勾选）\"}], \"summary\": {\"报告名称\": \"中创达无还本续贷授信尽调报告（线下普惠贷款首贷业务）\", \"报告类型\": \"授信业务尽职调查报告（线下普惠首贷/续贷）\", \"客户概况\": \"申请人******，成立于2021年3月22日，注册资本100万-500万元，实缴资本100万-500万元，员工14人、参保14人。法定代表人为******，36岁；实际控制人为马少华与******夫妇。企业为存量客户，本次申请续贷。已认定为国家级高新技术企业、省级创新型中小企业及科技型中小企业。\", \"主营业务与经营\": \"主营业务为工业炉窑行业节能环保燃烧设备的研发、制造和销售，核心产品为弥散式高温低氧燃烧技术相关设备。采购端与3-5家固定供应商合作，采用预付款加货到付款模式；生产端自行加工组件并现场组装交付；销售以线下直销为主，采取3+3+3+1分阶段收款模式。下游客户主要为有色金属制造行业企业，回款周期1-3个月。在手订单一份，合同金额100万以下。\", \"财务概况\": \"近三年营业收入均为500万-1000万，逐年缓慢增加。2025年毛利率30%-40%，净利润率约1%以下，经营现金流净额为正。截至2026年3月末净利润-0.4万元，因回款集中在下半年预计年底扭亏。资产总额200%以上，资产负债率60%-70%。应收账款占总资产比例较高，存货部分有积压减值风险。财务数据未经审计。\", \"授信方案\": \"申请无还本续贷流动资金贷款，授信额度不超过人民币100万以下，期限不长于1年，用途为无还本续贷。年化利率根据一年期LPR固定执行，按月付息到期一次还本。支付方式为全额自主支付。\", \"担保与还款\": \"担保方式：（1）苏州高新中小企业融资担保有限公司对不低于本金80%-90%提供保证担保；（2）实际控制人******提供个人连带责任保证。还款来源为企业经营性现金流。抵押物信息未披露具体内容。\", \"主要风险\": [\"申请人及担保企业名称在报告中均被脱敏处理，无法确认主体身份全称。\", \"财务报表显示近年净利润极薄甚至亏损（2024年净利润-4.46，2025年仅1%以下），盈利能力弱，且2026年一季度继续亏损。\", \"应收账款占比较高（总资产的100%-150%），回收不确定性较大；存货持有天数超200天，存在积压减值风险。\", \"对外担保余额虽小但明确为中创达在上海银行的贷款做担保，形成关联互保。\"], \"综合评价\": \"企业经营稳定，主营工业炉窑节能环保设备，拥有多项专利和高新技术资质，上下游合作关系良好，交叉验证未见重大异常。但财务数据显示盈利能力较弱、应收及存货占比高、近期持续微利或亏损，需关注其资金周转压力。担保结构由政策性担保公司和实控人共同承担，有一定保障。整体信用状况中等偏低，可持续经营能力有待观察。\"}}, {\"report_id\": \"rpt_67b208cdb9c834171513b0d3\", \"report_name\": \"微崇-杨征坤授信业务调查报告（制造型企业）\", \"report_type\": \"综合金融服务方案与授信业务调查报告\", \"score\": 93.75, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小型\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"半导体设备制造业，细分赛道为半导体前道量检测设备\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"半导体设备制造业，细分赛道为半导体前道量检测设备\"}, {\"name\": \"企业规模\", \"value\": \"小型\"}, {\"name\": \"主营业务\", \"value\": \"半导体前道量检测设备制造，主要产品包括二谐波晶圆检测设备ASPIRER3000、热波量测设备BRAVERY3000和全自动超声波缺陷检测设备CLARITY3000\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"5000万-1亿\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"1000万-5000万\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"-2760万元（约-1000万至-5000万区间内具体值）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（全文未披露经营活动产生的现金流量净额数据）\"}, {\"name\": \"是否集团客户\", \"value\": \"否\"}, {\"name\": \"是否科技型企业\", \"value\": \"是\"}, {\"name\": \"所有制性质\", \"value\": \"有限责任公司（民营/私人控股）\"}, {\"name\": \"授信金额\", \"value\": \"人民币1000万-5000万（敞口同额）\"}, {\"name\": \"授信期限\", \"value\": \"三年\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款额度\"}, {\"name\": \"担保方式\", \"value\": \"保证担保\"}, {\"name\": \"担保人\", \"value\": \"黄崇基（个人无限连带责任保证，不含配偶）\"}, {\"name\": \"担保物\", \"value\": \"无抵押或质押物\"}, {\"name\": \"贷款用途\", \"value\": \"补充日常流动资金需求\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为企业营业收入（预计2026年营收5000万-1亿）；第二还款来源为保证人代偿\"}, {\"name\": \"申请性质\", \"value\": \"首贷\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"微崇-杨征坤授信业务调查报告（制造型企业）\", \"报告类型\": \"综合金融服务方案与授信业务调查报告\", \"客户概况\": \"申请人为有限责任公司，成立于2021年3月，控股股东为******导体（持股100%），实际控制人为黄崇基。所属行业为半导体量检测设备制造（电子测量仪器制造），属支持型行业、科创型企业。累计股权融资约1亿-5亿元，最新投后估值预计超5亿元。\", \"主营业务与经营\": \"主营业务为半导体前道量检测设备制造，核心产品包括二谐波晶圆检测设备（国内首创）、热波量测设备和超声波显微镜设备。25年营收1000万-5000万元，经营规模较小但技术壁垒较高。下游客户主要为头部晶圆厂，订单验收周期2-3年。\", \"财务概况\": \"2025年末总资产5000万-1亿元，净资产1000万-5000万元；主营收入1000万-5000万元，毛利率60%-70%；净利润-2760万元（亏损持续收窄）；经营性现金流情况未披露。资产负债率50%-60%，流动比率1.64。报告未提供完整现金流量表数据。\", \"授信方案\": \"本次为首贷申请，拟申请流动资金贷款额度人民币1000万-5000万元，期限3年，利率固定3%-4%。设置远期共赢利息条款：企业估值每提高10%加收0.3%/年或上市时收取3%-4%/年，总成本上限6%-7%/年。单笔提款不超1年的按月付息到期还本；超过1年的按半年归还1%-2%本金。\", \"担保与还款\": \"担保方式为由实控人黄崇基（不含配偶）提供个人无限连带责任保证担保。主要还款来源为公司营业收入，预计26年营收5000万-1亿元。保证人名下具体资产信息未披露。\", \"主要风险\": [\"公司处于初创成长期，近三年连续大额亏损（23年净亏4028万元、24年5558万元、25年2760万元），盈利能力尚未转正，未来盈利预测存在不确定性。\", \"营运资金周转次数极低（0.16次），存货和应收账款占比较高，回款周期长（平均账期150天以上），流动性压力较大。\", \"实控人对外担保合计1000万-5000万元（均为关联公司借款担保），个人信用虽无逾期但或有负债风险需关注。\"], \"综合评价\": \"该公司聚焦半导体前道量检测设备细分赛道，拥有国内首创的二谐波晶圆检测核心技术，已获多轮头部机构投资并进入多家晶圆厂验证复购阶段。2025年营收快速增长至千万级，亏损逐步收窄，但当前仍处高研发投入期，财务表现较弱且营运效率偏低。本次授信以实控人保证担保作为风控抓手，整体方案匹配其成长阶段的资金需求，后续需密切跟踪订单交付进度、收入确认情况及外部融资进展。\"}}, {\"report_id\": \"rpt_ac47a33a1238e55410de0e95\", \"report_name\": \"杭州快乐女孩/浙江恒硕实业综合授信调查报告（首贷）\", \"report_type\": \"综合金融服务方案+授信业务调查报告\", \"score\": 93.75, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小微企业\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业（卫生用品和一次性使用医疗用品生产）、批发业（申请人二）\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业（卫生用品和一次性使用医疗用品生产）、批发业（申请人二）\"}, {\"name\": \"企业规模\", \"value\": \"小微企业\"}, {\"name\": \"主营业务\", \"value\": \"生活用纸（主要为纸巾）加工制造销售，产品主要销往东南亚地区（泰国）。申请人二承担集团对外销售尤其是自营出口。\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"1000万-5000万（2025年6月30日）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"100万-500万（2025年6月30日）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"50万-100万（2025年6月30日）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（全文未提供现金流量表数据）\"}, {\"name\": \"是否集团客户\", \"value\": \"是（******集团，共2户成员）\"}, {\"name\": \"是否科技型企业\", \"value\": \"不可提取（全文未提及高新技术企业、专精特新等资质或研发专利信息）\"}, {\"name\": \"所有制性质\", \"value\": \"民营（私营独资企业/家族企业）\"}, {\"name\": \"授信金额\", \"value\": \"人民币1000万-5000万（含敞口），两申请人各1000万-5000万\"}, {\"name\": \"授信期限\", \"value\": \"1年\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款\"}, {\"name\": \"担保方式\", \"value\": \"保证+抵押（信用+个人保证+房产抵押）\"}, {\"name\": \"担保人\", \"value\": \"华晨佐、华露芬、******（华晨佐配偶）；其中华露芬不追加其配偶\"}, {\"name\": \"担保物\", \"value\": \"商用房（杭州市富阳区鹿山街道依江路89号,211.62㎡,评估价值100万-500万）,住宅(富春街道江滨西大道96号春江花园景观楼8号1701室,324.5㎡,评估价值100万-500万)\"}, {\"name\": \"贷款用途\", \"value\": \"采购原材料\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为主营业务营收利润；第二还款来源为保证担保及抵押物处置\"}, {\"name\": \"申请性质\", \"value\": \"首贷\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"杭州快乐女孩/浙江恒硕实业综合授信调查报告（首贷）\", \"报告类型\": \"综合金融服务方案+授信业务调查报告\", \"客户概况\": \"客户为民营家族企业，实际控制人为华晨佐、华露芬姐弟。集团下辖两户：杭州快乐女孩卫生用品有限公司（制造业）成立于2007年，主营生活用纸加工销售；浙江恒硕实业有限公司（批发业）成立于2011年，定位集团销售公司。均未审计，信用等级aa-。资产总额1000万-5000万，年营收1亿-5亿，无银行融资负债。\", \"主营业务与经营\": \"主业为生活用纸（纸巾）生产与出口销售，产品主要销往泰国KUMA等客户。历经近20年经营，上下游渠道稳定。2024年起对外销售转移至恒硕实业。产能方面有25条生产线，年产约100万以下吨。目前因厂房改扩建租赁富春湾新城场地，租金100万-500万/年。\", \"财务概况\": \"申请人一（快乐女孩）：2024年末总资产1000万-5000万，净资产1000万-5000万，资产负债率4%-5%，营业收入1亿-5亿，净利润100万-500万；毛利率6%-7%。截至2025年6月30日销售收入5000万-1亿，净利润100万以下。现金流量分析报告未披露。\", \"授信方案\": \"本次申请首贷，集团合计申报流动资金贷款1000万-5000万元（敞口相同），期限1年，利率不低于2%-3%，用于采购原材料，用途明确。\", \"担保与还款\": \"担保方式为保证+抵押。保证人包括实控人华晨佐及其配偶、股东华露芬。抵押物为华晨佐名下住宅（面积324.5㎡，评估值100万-500万）和商用房（面积211.62㎡，评估值100万-500万）。第一还款来源为主营业务收入及利润，第二还款来源为担保代偿及抵押物处置变现。\", \"主要风险\": [\"财务报表未经审计，指标真实性缺乏外部验证依据，财务可信度评级为中或低。\", \"毛利率持续下滑：快乐女孩毛利率从2022年的10%-20%降至2025年中期的5%-6%；行业竞争激烈且受原材料价格波动影响。\", \"现金流数据缺失，报告中未提供任何现金流量表信息，无法直接判断经营活动现金流的充足性。\"], \"综合评价\": \"该集团属传统制造加贸易型企业，主营业务清晰，经营近20年积累稳定的供销渠道，近年营收增长但盈利空间收窄。整体负债极低，流动性良好，无存量银行贷款，征信记录干净。本次为首笔授信申请，金额较大而担保覆盖能力有限（抵押物评估值合计仅100万-500万级别），且财报未经审计、缺少现金流分析，存在一定信息缺口。\"}}, {\"report_id\": \"rpt_58e0b8a74d10db55dd7cc436\", \"report_name\": \"松江支行-张斌-普惠首贷流动资金贷款尽调报告\", \"report_type\": \"综合金融服务方案与授信业务尽职调查报告（首贷）\", \"score\": 93.75, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小微企业\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业（食品加工及销售）\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业（食品加工及销售）\"}, {\"name\": \"企业规模\", \"value\": \"小微企业\"}, {\"name\": \"主营业务\", \"value\": \"酱卤熟食生产、成品批发、线下终端零售；主营红肠、卤鹅、酱牛肉、凉拌预制菜等冷藏熟食。\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"1000万-5000万元\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"1000万-5000万元\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"10%-20%利润率对应金额不可直接提取\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（无直接数据）\"}, {\"name\": \"是否集团客户\", \"value\": \"否\"}, {\"name\": \"是否科技型企业\", \"value\": \"不可提取（无相关资质描述）\"}, {\"name\": \"所有制性质\", \"value\": \"民营/私人控股\"}, {\"name\": \"授信金额\", \"value\": \"人民币500万-1000万元\"}, {\"name\": \"授信期限\", \"value\": \"1年\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款（流贷）\"}, {\"name\": \"担保方式\", \"value\": \"政策性担保机构保证+法人夫妇全额连带责任保证\"}, {\"name\": \"担保人\", \"value\": \"上海市中小微企业政策性融资担保基金管理中心；石如燕及其配偶（无限连带责任保证）\"}, {\"name\": \"担保物\", \"value\": \"无抵押物和质押物\"}, {\"name\": \"贷款用途\", \"value\": \"支付货款等日常经营支出（原材料采购、货款支付）\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为企业经营活动产生的现金流；第二还款来源为担保代偿及保证人连带责任偿付。\"}, {\"name\": \"申请性质\", \"value\": \"首贷\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"松江支行-张斌-普惠首贷流动资金贷款尽调报告\", \"报告类型\": \"综合金融服务方案与授信业务尽职调查报告（首贷）\", \"客户概况\": \"客户成立于2016年，主营酱卤熟食制造与销售，为小微企业、我行新增首贷客户。实控人石如燕夫妇持股并经营，深耕行业二十余年；另一股东不参与经营。注册地上海市松江区，租赁面积1733㎡。无股权代持/质押/冻结。\", \"主营业务与经营\": \"集卤制品生产、批发、终端零售于一体，自有品牌“羽燕潮州鹅”“狗撵鸭”，产品包括红肠、卤鹅等冷藏熟食。自有冷链车队配送上海200余家社区门店、商超餐饮。近三年营收从100万-500万升至1000万-5000万，持续高速增长。上下游合作周期均超3年，账期2-3个月。\", \"财务概况\": \"2025年末资产总额约200%以上万元级区间，负债率100%-150%。货币资金占比较低，存货占用较大。近三年净利润：2023年亏损，2024-2025年盈利但账面利润低于实际，真实净利率约4%-6%。即期(2026.1-5)开票收入100万-500万。经营性现金流匹配良好，存在公私账户收款分流情况。财务数据未经审计。\", \"授信方案\": \"申请1年期流动资金贷款500万-1000万，固定利率（1年期LPR加点），按月付息到期一次还本，自主支付用于原材料采购等日常支出。为首贷业务。\", \"担保与还款\": \"担保组合：上海市中小微企******管理中心提供80%-90%本金担保，追加实控人石如燕夫妇全额连带责任保证。还款来源为企业稳定经营的营业收入。\", \"主要风险\": [\"企业公私资金混用严重，大量货款通过法人个人微信支付宝收取，对公归集度低，影响第一还款来源的完整监控。\", \"企业无自有不动产抵押，主要依赖政策性担保+自然人保证，若政策或保证人资质变化可能影响增信有效性。\", \"关联方较多且部分关联企业经营规模大，实控人及配偶对外担保余额达500万-1000万，需关注或有负债风险传导。\", \"财务报表未审，账面利润因税务规划偏低，存货囤积超千万且呈降价趋势，可能存在减值风险和流动性压力。\"], \"综合评价\": \"该户处于快速成长期，主营业务清晰，下游渠道稳定，盈利能力逐步改善。融资用途明确契合季节性备货需求，但财务规范性较弱，公私资金分离和关联担保是主要信息缺口与管理挑战。整体经营基本面稳健，具备一定偿债能力基础。\"}}, {\"report_id\": \"rpt_d8dcb22afcbf832721b7e253\", \"report_name\": \"苏州分行-安川泰科技（ACT）流动资金贷款送审意见书\", \"report_type\": \"送审意见书\", \"score\": 93.75, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小型企业\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业-仪器仪表制造业-其他仪器仪表制造业-其他仪器仪表制造业\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业-仪器仪表制造业-其他仪器仪表制造业-其他仪器仪表制造业\"}, {\"name\": \"企业规模\", \"value\": \"小型企业\"}, {\"name\": \"主营业务\", \"value\": \"工业自动化、通讯、汽车电子、物联网、新能源、网络科技领域内的技术开发、技术咨询、技术服务；智能装备的研发、设计、制造；集成线路板及其零配件生产与销售；从事上述产品及技术的进出口业务。实际主营为工控自动化产品的PCBA代工，主要服务汇川等客户。\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"5000万-1亿（2025年即期）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"5000万-1亿（2025年即期）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"-142至50万元之间（2025年即期约为10以下至50？原文模糊）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（未提供）\"}, {\"name\": \"是否集团客户\", \"value\": \"是\"}, {\"name\": \"是否科技型企业\", \"value\": \"是\"}, {\"name\": \"所有制性质\", \"value\": \"国有相对控股（珠海国资委为实际控制人）\"}, {\"name\": \"授信金额\", \"value\": \"1000万-5000万元\"}, {\"name\": \"授信期限\", \"value\": \"1年\"}, {\"name\": \"授信品种\", \"value\": \"企业流动资金贷款\"}, {\"name\": \"担保方式\", \"value\": \"信用\"}, {\"name\": \"担保人\", \"value\": \"无保证人\"}, {\"name\": \"担保物\", \"value\": \"无抵押物和质押物\"}, {\"name\": \"贷款用途\", \"value\": \"日常经营周转\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为企业经营性收入，具体来自下游客户的加工费回款；第二还款来源未明确提及\"}, {\"name\": \"申请性质\", \"value\": \"首贷\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"苏州分行-安川泰科技（ACT）流动资金贷款送审意见书\", \"报告类型\": \"送审意见书\", \"客户概况\": \"经营主体为******，成立于2017年8月9日，注册地址苏州工业园区金******1号东景工业坊22幢、27幢。企业类型为公司/国有相对控股，行业属制造业-仪器仪表制造业，规模小型企业。实际控制人为珠海国资委，母公司深圳安科讯电子于2023年被*****集团收购。法人代表余道义，从业经验丰富。近三年社保人数159人至178人，纳税等级A级，信用评级a+(2025-07-31)。\", \"主营业务与经营\": \"主营工控自动化、汽车电子、物联网等产品的PCBA制造与代工服务，以SMT贴片和DIP插件为核心工艺，核心客户为汇川技术，占营收80%-90%。2024年起拓展思格新能源等新客户。在手订单框架协议金额1000万-5000万元。预计2026年搬迁扩产并加大设备投入。\", \"财务概况\": \"报告未披露精确财务数据，仅提供区间值：总资产约5000万-1亿，净资产约500万-1000万，资产负债率90%左右（扣除关联借款后60%-70%），销售收入约5000万-1亿元，净利润波动较大（2022年亏损438万元，2023年盈利500-1000万元，2024年亏损142万元）。毛利率10%-20%，流动比率及速动比率均低于1。现金流情况未明确说明。报表经审计。\", \"授信方案\": \"申请授信品种为企业流动资金贷款，首贷，申请金额1000万-5000万元，期限1年，用途日常经营周转，支付方式自主支付，还本付息方式到期一次还本并按月付息。定价固定利率，参考LPR加点。纳入******集团统一授信管理。\", \"担保与还款\": \"担保方式为信用。还款来源主要依靠公司经营性现金流入。无抵押或第三方保证安排。\", \"主要风险\": [\"下游客户高度集中：前五大销售中第一大客户汇川占比80%-90%，存在单一客户依赖风险；虽已拓展新客户但尚未规模化。\", \"财务状况偏弱：资产负债率高达90%（剔除应付母公司的其他应付款后仍达60%-70%），盈利能力薄弱且近年利润波动大，短期偿债指标偏低。\", \"信息缺口较多：部分关键字段如注册资本实收资本具体数值、母公司财务报表数据、企业主配偶征信情况及个人资产明细均为“报告未披露”或模糊表述，影响全面评估。\"], \"综合评价\": \"借款人背靠国资背景的母公司，深耕高端智能制造领域多年，核心客户汇川技术实力强劲、粘性高，所处行业处于上升期。但自身财务杠杆较高、盈利能力较弱，且下游集中度过高风险突出。本次授信方案为信用方式，缺乏实质性增信措施。整体而言，企业经营基础尚可，但信用风险和不确定性不容忽视。\"}}, {\"report_id\": \"rpt_2f9cc8207002d74107144364\", \"report_name\": \"苏州分行协同创新智能制造装备有限公司授信送审意见书（普惠及小企业业务模板）\", \"report_type\": \"上海银行送审意见书（普惠及小企业业务模板）\", \"score\": 93.75, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小型企业\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业-专用设备制造业-环保、邮政、社会公共服务及其他专用设备制造-其他专用设备制造\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业-专用设备制造业-环保、邮政、社会公共服务及其他专用设备制造-其他专用设备制造\"}, {\"name\": \"企业规模\", \"value\": \"小型企业\"}, {\"name\": \"主营业务\", \"value\": \"研发、生产、销售智能设备、模具、传感器、检测设备、自动化设备，以及工业互联网标识解析二级节点运营和智能制造系统解决方案\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"1亿-5亿（截至2026年3月末）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"1万-5万（截至2026年3月末）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"100万-500万（截至2026年3月末）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（未披露或完全脱敏）\"}, {\"name\": \"是否集团客户\", \"value\": \"是\"}, {\"name\": \"是否科技型企业\", \"value\": \"是\"}, {\"name\": \"所有制性质\", \"value\": \"民营（私人相对控股）\"}, {\"name\": \"授信金额\", \"value\": \"1000万-5000万元（本次申请，原额度续借）\"}, {\"name\": \"授信期限\", \"value\": \"1年\"}, {\"name\": \"授信品种\", \"value\": \"企业流动资金贷款\"}, {\"name\": \"担保方式\", \"value\": \"保证+风险分担组合：实际控制人夫妇连带责任保证 + 政府风险分担（银行30%-40%，担保机构等代偿）\"}, {\"name\": \"担保人\", \"value\": \"实际控制人******及其配偶陆******\"}, {\"name\": \"担保物\", \"value\": \"无抵押或质押物设定\"}, {\"name\": \"贷款用途\", \"value\": \"企业日常经营周转\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为企业自身经营性收入；第二还款来源为实际控制人夫妇连带责任保证\"}, {\"name\": \"申请性质\", \"value\": \"续借（首贷  续借，未增加/减少敞口）\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否（明确勾选非关联交易）\"}], \"summary\": {\"报告名称\": \"苏州分行协同创新智能制造装备有限公司授信送审意见书（普惠及小企业业务模板）\", \"报告类型\": \"上海银行送审意见书（普惠及小企业业务模板）\", \"客户概况\": \"申请人为******，成立于2017年6月9日，注册资本约5929.85万元，私人相对控股，小型企业，制造业-专用设备制造业。属高新技术企业、瞪羚企业、国家级专精特新小巨人企业。2026年5月地方征信分677分。\", \"主营业务与经营\": \"主营研发、生产、销售智能设备、模具、传感器、检测设备、自动化设备等，并承担工业互联网标识解析二级节点建设与运营。下设智能模具事业部、自动化装备事业部、光纤传感器事业部、智能制造服务事业部，提供一体化软硬件解决方案。拥有专利200项，核心团队含博硕超20人。\", \"财务概况\": \"截至2026年3月末总资产1亿-5亿元，净资产1亿-5亿元，资产负债率50%-60%。近三年营业收入分别为1亿-5亿元、1亿-5亿元、1亿-5亿元；净利润1000万-5000万元。报告未披露审计结论。即期销售收入下降至5000万-1亿元，毛利率15.19%，现金流情况报告未明确说明。\", \"授信方案\": \"本次申请“信保贷”项下流动资金贷款1000万-5000万元，期限1年，用途为企业日常经营周转，为原额度续借。支付方式为自主支付。\", \"担保与还款\": \"担保方式：实际控制人夫妇连带责任保证，并在符合相关要求前提下，我行承担30%-40%风险，政府风险分担资金池10%-20%、其他机构合计补偿剩余部分。还款来源主要依靠企业经营收入及股权融资补充。\", \"主要风险\": [\"财务数据区间化严重，关键指标如营收、利润均以范围呈现，无法准确评估偿债能力。\", \"应收账款金额较大且集中于一年以内，但坏账计提政策和回款保障措施未充分披露。\", \"他行授信机构多达14家，总余额上升趋势明显，存在过度授信和信贷政策变动风险。\", \"实际控制人对外担保余额较高（对企业担保1亿-5亿元），或有负债风险需关注。\"], \"综合评价\": \"客户属于高端智能装备制造行业，技术实力较强，获多项国家资质和政府支持，近年营收增长较快。但财务信息模糊，依赖区间数判断；债务规模扩张快，外部融资集中度高，实际控制人担保负担重。整体资信良好无逾期不良，综合来看发展潜力大但信用敞口管理压力显著。\"}}, {\"report_id\": \"rpt_b504f8d7bb448f9035a34eb3\", \"report_name\": \"苏州圣汇装备有限公司综合授信业务调查报告（首贷）\", \"report_type\": \"综合金融服务方案及授信业务调查报告（首贷）\", \"score\": 93.75, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"中小型民营企业\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"专用设备制造业\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"专用设备制造业\"}, {\"name\": \"企业规模\", \"value\": \"中小型民营企业\"}, {\"name\": \"主营业务\", \"value\": \"专业从事Ⅰ/Ⅱ/Ⅲ类压力容器、低温储运装备及工业炉的设计、制造和销售\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"5万-10万元（2026年3月）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"5万-10万元（2026年3月）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"-3592万元（2026年3月累计）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"-3126万元（2026年3月）\"}, {\"name\": \"是否集团客户\", \"value\": \"是\"}, {\"name\": \"是否科技型企业\", \"value\": \"是\"}, {\"name\": \"所有制性质\", \"value\": \"民营（有限责任公司）\"}, {\"name\": \"授信金额\", \"value\": \"不超过人民币1亿-5亿元（敞口不超过1亿-5亿元，其中1000万-5000万为备用额度）\"}, {\"name\": \"授信期限\", \"value\": \"1年\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款、银行承兑汇票、非融资性保函(投标保函、预付款保函、履约保函,质量维修保函)、国内信用证\"}, {\"name\": \"担保方式\", \"value\": \"保证担保（连带责任保证）\"}, {\"name\": \"担保人\", \"value\": \"******有限公司\"}, {\"name\": \"担保物\", \"value\": \"不涉及抵质押担保\"}, {\"name\": \"贷款用途\", \"value\": \"日常经营周转\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为申请人销售收入，第二还款来源为担保人的销售收入\"}, {\"name\": \"申请性质\", \"value\": \"首贷\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"苏州圣汇装备有限公司综合授信业务调查报告（首贷）\", \"报告类型\": \"综合金融服务方案及授信业务调查报告（首贷）\", \"客户概况\": \"苏州圣汇装备有限公司是专注于专用设备制造业的中小型民营企业，主营压力容器、低温储运装备及工业炉制造，控股股东为荣盛集团。公司拥有国家级专精特新小巨人及高新技术企业资质，信用等级BBB。2023-2025年主营业务收入均在5亿元以上但逐年下滑。与我行为首次合作。\", \"主营业务与经营\": \"专业从事Ⅰ/Ⅱ/Ⅲ类压力容器、低温装备、球罐、船用装备等的设计、制造和销售，产品包括非标压力容器、LNG系列储运装备、球形储罐等。下游主要为石化行业客户，付款方式以承兑为主，账期6-9个月；上游采购原材料基本无账期。公司在手订单5亿以上，其中集团内1-2.5亿，集团外含重点项目。\", \"财务概况\": \"报告未披露具体财务数据全貌。2023-2025年营业收入均为5-10亿区间且逐年下降，毛利率从14.94%降至9.09%，净利润连续亏损（分别为-194万、1000-5000万、-1716万）。经营性净现金流近三年持续为正，投资性活动规模较小，筹资性净现金流持续为负。资产负债率70%-80%，流动比率低于1，短期偿债指标偏弱。应收账款周转天数延长至185天。\", \"授信方案\": \"申请性质为首贷，拟给予不超过人民币1亿-5亿的综合授信额度，敞口同样金额（含1000万-5000万备用额度），期限1年。品种包括流动资金贷款、银行承兑汇票、非融资性保函（投标/预付款/履约/质量维修保函）、国内信用证。流贷利率不低于2%-3%/年，银承保证金比例10%-20%。用途为日常经营周转及置换他行贷款。\", \"担保与还款\": \"由******有限公司提供连带责任保证担保。第一还款来源为申请人销售收入，第二还款来源为担保人销售收入。不涉及抵质押担保。\", \"主要风险\": [\"申请人近年营收持续下滑，2024年、2025年均出现较大额营业利润亏损（2025年营业利润约-1424万元），盈利能力恶化。\", \"应收账款周转天数自97天上升至185天，回款周期长于预期，资金占用加大流动性风险；流动比率与速动比率均低于1，短期偿债能力偏弱。\", \"征信报告中存在历史垫款记录（42笔银票垫款），原因为前总经理挪用公款涉诉导致账户冻结，虽已处理但仍构成信用瑕疵。\"], \"综合评价\": \"苏州圣汇装备有限公司为荣盛集团旗下高端装备制造子公司，技术实力较强并持有重要资质，在手订单充足。但近年来收入下滑、持续亏损、营运资金周转较慢、短期流动性趋紧，同时历史上曾因内部管理问题产生过征信垫款。本次授信有世界500强母公司全额保证担保，整体风险可控，但需加强后续资金用途监控及应收应付款跟踪。\"}}, {\"report_id\": \"rpt_a06353a2c50492ec8826dd6b\", \"report_name\": \"苏州火零科技普惠首贷综合金融服务方案（尽调报告）\", \"report_type\": \"综合金融服务方案（含尽调报告模板）\", \"score\": 93.75, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小型（从业人数11人，营收1000万-5000万）\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"军工设备制造业（军用雷达、电子对抗等）\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"军工设备制造业（军用雷达、电子对抗等）\"}, {\"name\": \"企业规模\", \"value\": \"小型（从业人数11人，营收1000万-5000万）\"}, {\"name\": \"主营业务\", \"value\": \"军民用雷达系统、海上风电监测、辅助决策系统的研发、定制化生产与售后\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"200%以上（即>2亿元，但具体数值脱敏）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"不可提取（仅披露负债总额同比变化比例，无绝对值）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"-57万元（亏损约57万）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（报告中无现金流量表数据）\"}, {\"name\": \"是否集团客户\", \"value\": \"是\"}, {\"name\": \"是否科技型企业\", \"value\": \"是（高新技术企业、专精特新、瞪羚企业）\"}, {\"name\": \"所有制性质\", \"value\": \"民营控股（实控人马东林个人持股10%-20%，其余股东多为投资机构）\"}, {\"name\": \"授信金额\", \"value\": \"100万-500万元人民币\"}, {\"name\": \"授信期限\", \"value\": \"12个月\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款\"}, {\"name\": \"担保方式\", \"value\": \"信用\"}, {\"name\": \"担保人\", \"value\": \"无保证人（纯信用贷款）\"}, {\"name\": \"担保物\", \"value\": \"无抵押质押物（纯信用贷款）\"}, {\"name\": \"贷款用途\", \"value\": \"日常经营周转（补充营运资金缺口）\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为企业经营产生的稳定现金流（含在手订单预计回款），第二还款来源未明确说明\"}, {\"name\": \"申请性质\", \"value\": \"首贷\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"苏州火零科技普惠首贷综合金融服务方案（尽调报告）\", \"报告类型\": \"综合金融服务方案（含尽调报告模板）\", \"客户概况\": \"企业2023年10月成立，法人马东林，主营军民用雷达及海洋探测装备全产业链研发生产，属军工设备制造行业。高新技术、专精特新、瞪羚企业；国资******控A轮投资后持股约13%，投后估值7亿元。\", \"主营业务与经营\": \"主营业务为军用产品占营收80%-90%，民用海上风电业务占20%-30%；经营模式为客户定制化生产，交付周期约3个月；当前在手订单1000万-5000万元，另有某重点项目待落地。主要交易对手集中于关联方******软件采购占比80%-90%。\", \"财务概况\": \"2024年亏损，无主营收入；2025年实现营收1000万-5000万，净利润盈利，主营利润率约13.41%、净利率21.79%；即期2026年3月暂无主营收入，月度微亏。货币资金充裕，资产总额以长期股权投资为主（对北京******持股）。应付账款500万-1000万。现金流方面报告未披露完整现金流量表数据。\", \"授信方案\": \"申请纯信用流动资金贷款100万-500万元，期限12个月，用于日常经营周转，自主支付，到期一次还本按月付息，利率2%-3%（1年期LPR加点区间），本次为首贷。\", \"担保与还款\": \"担保方式为纯信用，不涉及抵质押或保证人。还款来源为企业经营性现金流入，预计2026年全年营收1000万-5000万可覆盖债务。\", \"主要风险\": [\"企业经营高度依赖军方客户，证照资质尚在办理中，目前销售主要通过关联公司进行，若资质落地延迟可能影响后续订单确认和收入增长。\", \"初创阶段营收波动较大，项目制导致阶段性垫资压力大，2025年末应付账款500万-1000万，且上游需现款预付，流动性管理存在缺口。\", \"实控人马东林及其配偶征信未被查询，个人资产信息不予提供，实际控制人层面风险敞口不明。\"], \"综合评价\": \"企业成立于2023年，属于军民融合领域的高新技术军工配套商，技术实力较强且背靠国有资本支持，2025年起已实现规模化创收并扭亏为盈，在手订单支撑未来一定期间营收。但作为首贷客户，其财务历史较短、应收账款与存货规模攀升明显、对外融资结构单一（已有他行流贷余额500万-1000万）、实际控制人信息缺失等问题需要关注。整体看，该笔授信用途真实、还款来源初步可见，但风险缓释措施不足。\"}}, {\"report_id\": \"rpt_822a199dc1171ee02254c88f\", \"report_name\": \"闵行支行-新材料企业流动资金贷款尽调报告\", \"report_type\": \"授信业务尽调报告（线下普惠贷款首贷业务）\", \"score\": 93.75, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小型企业（从业人数58人，营收100万-500万元，总资产区间5000万-1亿/1000万-5000万）\", \"similarity\": 1.0}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业（镍钛合金材料研发、设计、制造与测试评估）\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业（镍钛合金材料研发、设计、制造与测试评估）\"}, {\"name\": \"企业规模\", \"value\": \"小型企业（从业人数58人，营收100万-500万元，总资产区间5000万-1亿/1000万-5000万）\"}, {\"name\": \"主营业务\", \"value\": \"SMA镍钛合金材料的研发、设计、制造与测试评估，销售SMA驱动丝材及驱控系统\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"1000万-5000万元（2026年3月末合并口径）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"不可提取（仅给出资产负债率10%-20%，无具体数值）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"-164万元（2026年3月单体报表）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（未提供现金流量表）\"}, {\"name\": \"是否集团客户\", \"value\": \"否\"}, {\"name\": \"是否科技型企业\", \"value\": \"是（国家高新技术企业资质？原文未明示，但有专利等科创属性）\"}, {\"name\": \"所有制性质\", \"value\": \"民营/私人控股（实际控制人为自然人金明江）\"}, {\"name\": \"授信金额\", \"value\": \"1000万-5000万元（含备用额度500万-1000万上报审批后启用）\"}, {\"name\": \"授信期限\", \"value\": \"1年\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款\"}, {\"name\": \"担保方式\", \"value\": \"连带责任保证担保（子公司提供）、信用（其他技担保脱敏）\"}, {\"name\": \"担保人\", \"value\": \"******技（******（子公司）\"}, {\"name\": \"担保物\", \"value\": \"无抵押或质押物\"}, {\"name\": \"贷款用途\", \"value\": \"用于采购原材料、支付工资等经营性支出\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为企业经营性收入；第二还款来源为保证人代偿\"}, {\"name\": \"申请性质\", \"value\": \"增量续借\"}, {\"name\": \"是否我行关联企业\", \"value\": \"部分（无法从原文确认是否为关联企业）\"}], \"summary\": {\"报告名称\": \"闵行支行-新材料企业流动资金贷款尽调报告\", \"报告类型\": \"授信业务尽调报告（线下普惠贷款首贷业务）\", \"客户概况\": \"客户成立于2022年7月，主营SMA镍钛合金材料的研发、设计、制造与测试评估，核心团队来自上海交大、中科院等。实控人金明江，持股20%-30%。属民营企业、高新技术初创公司。参保人数22人，注册资本1000万-5000万，实缴资本500万-1000万。经营地址为上海市闵行区租赁场所。\", \"主营业务与经营\": \"主营业务为SMA驱动丝材及驱控系统，产品覆盖OIS马达、触觉马达、控制阀芯等领域。采用‘材料+器件+系统’三位一体模式，子公司江苏******负责生产。采购端预付后发货，账期0-30天；销售端账期三个月左右。已与韶音科技签订框架合同，并与新思考电机等合作，在手订单预计2026年带来营收约500万-1000万。\", \"财务概况\": \"2025年合并营收100万-500万，净利润-831万元；截至2026年3月末总资产1000万-5000万，净资产1000万-5000万，资产负债率10%-20%；货币资金充足且主要为融资款，毛利率27%，但持续亏损，尚未量产。现金流主要依赖股权融资和少量经营性流入。\", \"授信方案\": \"申请增量续借流动资金贷款，授信金额不超过1000万-5000万（备用额度500万-1000万），期限1年，用途为采购原材料、支付工资等经营性支出，利率按一年期LPR+/-30BP固定利率执行，全额自主支付。\", \"担保与还款\": \"担保方式为由关联方/子公司******技提供连带责任保证担保。还款来源为企业未来量产后的营业收入及后续股权融资款项。\", \"主要风险\": [\"申请人尚处于发展初期未实现规模化量产，连续三年亏损（2023年至2025年累计净亏损超2000万元），盈利前景存在较大不确定性。\", \"关键财务数据以区间范围披露（如营收100万-500万、利润总额-839至-981万元等），无法精确判断实际偿债能力。\", \"实控人为高校在职人员不提供个人连带责任保证，且其配偶资产信息均未披露，第二还款来源保障较弱。\"], \"综合评价\": \"该企业属于高科创属性新材料初创公司，技术壁垒较高，已有初步市场突破和在手订单，但至今仍处研发和小批量阶段，持续亏损且高度依赖外部融资支撑运营。本次增贷主要用于扩大量产前的营运资金储备，整体风险可控性依赖于后续产能释放和新订单转化进度。\"}}, {\"report_id\": \"rpt_53e7038c38444d401ffe5529\", \"report_name\": \"上海银行送审意见书（杭州分行-纺织业）\", \"report_type\": \"送审意见书及综合金融服务方案\", \"score\": 88.75, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"从业人员246人，近三年营业收入区间1亿-5亿元，总资产5亿以上，未明示大型、中型或小型认定；结合数据判断为大型\", \"similarity\": 0.7}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业\", \"similarity\": 1.0}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业\"}, {\"name\": \"企业规模\", \"value\": \"从业人员246人，近三年营业收入区间1亿-5亿元，总资产5亿以上，未明示大型、中型或小型认定；结合数据判断为大型\"}, {\"name\": \"主营业务\", \"value\": \"机织布研发、生产、销售，核心产品包括机织布、机织布加工、整经加工、气囊布\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"合并总资产5亿以上（截止2025年6月末）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"总负债1亿-5亿（截止2025年6月末）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"净利润约-467.71万元（2025年1-6月）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"经营活动净现金流为正，具体金额脱敏不可提取\"}, {\"name\": \"是否集团客户\", \"value\": \"不涉及集团统一授信\"}, {\"name\": \"是否科技型企业\", \"value\": \"是（国家级高新技术企业、省级专精特新企业、科技型中小企业）\"}, {\"name\": \"所有制性质\", \"value\": \"民营控股（实控人为******、******夫妇，合计持股64.24%，均为自然人）\"}, {\"name\": \"授信金额\", \"value\": \"综合授信敞口不超过等值人民币1000万-5000万\"}, {\"name\": \"授信期限\", \"value\": \"不长于1年\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款额度、票据承兑额度\"}, {\"name\": \"担保方式\", \"value\": \"自然人保证（个人连带责任保证）\"}, {\"name\": \"担保人\", \"value\": \"******、******夫妇\"}, {\"name\": \"担保物\", \"value\": \"无抵押担保，不涉及担保物\"}, {\"name\": \"贷款用途\", \"value\": \"采购原材料、支付工资、置换他行贷款\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为企业日常经营收入\"}, {\"name\": \"申请性质\", \"value\": \"首次申请\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"上海银行送审意见书（杭州分行-纺织业）\", \"报告类型\": \"送审意见书及综合金融服务方案\", \"客户概况\": \"申请人为新三板上市公司，主营机织布研发、生产与销售，控股股东为******夫妇（一致行动人），合计持股64.24%。企业被认定为国家级高新技术企业、科技型中小企业、省级专精特新企业。行业类别为制造业，从业人员246人。\", \"主营业务与经营\": \"主营业务包括机织布、机织布加工、整经加工和气囊布四大板块。传统机织布贡献超90%收入；气囊布为一体制成型高端产品，已通过IATF16949认证并获头部零部件厂商验证，2025年6月量产。经营模式以订单驱动为主，采购采用集中采购+长期协议，销售直销与经销商结合。\", \"财务概况\": \"截至2025年6月末合并总资产5亿以上，净资产1亿-5亿，资产负债率70%-80%。近三年主营收入持续增长但增速放缓至8.13%，毛利率从12.08%降至5.84%；净利润连续亏损且亏损扩大（2024年净亏约2045万元）。经营活动现金流持续为正，投资活动现金净流出较大。报告未披露具体营收金额。\", \"授信方案\": \"本次首次申请流动资金贷款，金额1000万-5000万，期限12个月，用途为采购原材料、支付工资和置换他行贷款，受托支付。利率固定为LPR减40基点（不低于2%-3%）。\", \"担保与还款\": \"担保方式为实控人******、******夫妇提供个人连带责任保证。还款来源主要来自申请人日常经营。抵押物方面，实控人名下海宁百合新城别墅已抵押，其余房产未抵押。\", \"主要风险\": [\"公司连续两年净利润大额亏损（2024年净亏约2045万元），累计未分配利润负值，削弱持续盈利能力。\", \"一年内到期有息负债保障倍数仅0.21倍，短期偿债能力偏弱。\", \"应收账款周转天数远高于行业均值（180天 vs 75天），回款效率偏低。\", \"气囊布业务虽已量产但仍处于市场验证期，尚未形成规模效应，未来收入存在不确定性。\"], \"综合评价\": \"企业正处于传统业务承压与新业务转型阶段：传统机织布竞争加剧致毛利下滑，高端气囊布刚起步，整体盈利仍处亏损状态。公司资产负债率高，短期流动性紧张，但有持续的经营活动现金流入支撑运营。实际控制人家庭资产较充裕，提供个人连带担保。本次为首笔合作，敞口较小，属谨慎介入。\"}}, {\"report_id\": \"rpt_8c734e821d252ab932267f71\", \"report_name\": \"奉贤支行-费敏-制造业-001授信业务调查报告（增量续借）\", \"report_type\": \"授信业务调查报告（制造型企业）\", \"score\": 82.5, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"黄大型企业/小型企业（报告原文显示两者并存，无法确定最终认定结果）\", \"similarity\": 0.7}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业-专用设备制造业-环保、邮政、社会公共服务及其他专用设备制造-环境保护专用设备制造\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业-专用设备制造业-环保、邮政、社会公共服务及其他专用设备制造-环境保护专用设备制造\"}, {\"name\": \"企业规模\", \"value\": \"黄大型企业/小型企业（报告原文显示两者并存，无法确定最终认定结果）\"}, {\"name\": \"主营业务\", \"value\": \"废弃电器电子产品处理；报废机动车回收；报废机动车拆解；危险废物经营；报废电动汽车回收拆解。\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"5万-10万元（2026年3月）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"由总资产区间和资产负债率推算约1万-2万之间，具体值不可提取\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"-640万元（2026年3月）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（报告现金流量表数据截止至2025年度，无2026年一季度数据）\"}, {\"name\": \"是否集团客户\", \"value\": \"是\"}, {\"name\": \"是否科技型企业\", \"value\": \"是\"}, {\"name\": \"所有制性质\", \"value\": \"私人绝对控股（民营）\"}, {\"name\": \"授信金额\", \"value\": \"人民币1亿-5亿元（敞口1亿-5亿元）\"}, {\"name\": \"授信期限\", \"value\": \"12个月、18个月\"}, {\"name\": \"授信品种\", \"value\": \"一年期循环流贷、一年期流贷、18个月流贷\"}, {\"name\": \"担保方式\", \"value\": \"信用\"}, {\"name\": \"担保人\", \"value\": \"无\"}, {\"name\": \"担保物\", \"value\": \"无\"}, {\"name\": \"贷款用途\", \"value\": \"用于采购原材料等日常经营周转\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为销售收入\"}, {\"name\": \"申请性质\", \"value\": \"增量续借\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"奉贤支行-费敏-制造业-001授信业务调查报告（增量续借）\", \"报告类型\": \"授信业务调查报告（制造型企业）\", \"客户概况\": \"申请人成立于2006年，私人绝对控股制造业企业（废弃电器电子产品处理等），为集团核心企业之一；实际控制人黄尚渭。报告未披露注册资本具体金额。信用等级a(2025-04-25)。员工103人（2024年）。\", \"主营业务与经营\": \"主营报废机动车回收拆解、废旧家电拆解及危废无害化处置，以“报废机动车资源化”为核心，拥有多项发明专利和全品类电子废物拆解资质；下游客户包括大众、通用等大型企业；上游采购付款方式多为款到发货，下游账期1-2个月。\", \"财务概况\": \"未经审计报表显示：2025年主营业务收入5亿以上（同比增50%-60%），净利润1000万-5000万（同比增10%-20%）；截至2025年末总资产5万-10亿，净资产1万-5亿，资产负债率10%-20%；经营活动现金流净额-7057万元（主要因关联占用）；货币资金1000万-5000万。应收账款周转天数改善至20%-30%。\", \"授信方案\": \"本次申请增量续借人民币流动资金贷款总额1亿-5亿元，含一年期流贷1000万-5000万、一年期循环流贷1000万-5000万、18个月流贷1000万-5000万；利率不低于固定2%-3%，期限12/18个月；用途为支付货款等日常经营周转。\", \"担保与还款\": \"担保方式为信用，无抵质押物或保证人。第一还款来源为销售收入，我行结算回款占比90%以上。\", \"主要风险\": [\"2025年经营活动现金流转负（-7057万元），主因为集团内关联占款导致自身资金留存欠佳。\", \"本笔授信为信用方式，无任何抵押或保证，担保偏弱。\", \"存在一起承揽合同纠纷案件（案值约百余万元），待开庭审理结果不确定。\", \"大宗商品（废钢）价格低位波动持续影响毛利率水平。\"], \"综合评价\": \"申请人为上海市区域性大型再生资源回收基地，受益于国补政策主业增长明显，与银行合作深入且回报较高；但2025年经营性现金流大幅转负系由关联占款引起，叠加诉讼风险和行业价格波动，需关注其自身资金独立性和盈利能力稳定性。\"}}, {\"report_id\": \"rpt_f26dc4c53c239e30dc69eca9\", \"report_name\": \"徐汇支行-张欣欣-制造业综合金融服务方案（授信业务调查报告）\", \"report_type\": \"综合金融服务方案与授信业务调查报告\", \"score\": 82.5, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"小型或中型经营主体，营收1000万-5000万\", \"similarity\": 0.7}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"金属制品制造业\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"金属制品制造业\"}, {\"name\": \"企业规模\", \"value\": \"小型或中型经营主体，营收1000万-5000万\"}, {\"name\": \"主营业务\", \"value\": \"研究、生产和销售锡焊材料及相关焊接产品，涵盖焊锡膏、焊锡片、助焊剂、焊锡棒和焊锡丝等\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"1000万-5000万（2025年末）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"100万-500万（2025年末）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"-11万元左右（2025年）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"-205万元（2025年）\"}, {\"name\": \"是否集团客户\", \"value\": \"不可提取（无任何关于集团的陈述）\"}, {\"name\": \"是否科技型企业\", \"value\": \"是，拥有高新技术、专精特新标识及20个有效专利权\"}, {\"name\": \"所有制性质\", \"value\": \"民营股份有限公司（实际控制人脱敏无法确认穿透后性质）\"}, {\"name\": \"授信金额\", \"value\": \"本次申请额度500万-1000万（敞口相同）\"}, {\"name\": \"授信期限\", \"value\": \"1年\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款\"}, {\"name\": \"担保方式\", \"value\": \"知识产权质押+法定代表人夫妇保证担保\"}, {\"name\": \"担保人\", \"value\": \"法定代表人与配偶（姓名均脱敏）\"}, {\"name\": \"担保物\", \"value\": \"一项专利权质押（一种水洗低温无铅锡膏及其制备方法）\"}, {\"name\": \"贷款用途\", \"value\": \"支付货款等企业日常经营周转\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为企业经营收入，覆盖本笔授信金额\"}, {\"name\": \"申请性质\", \"value\": \"首贷\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"徐汇支行-张欣欣-制造业综合金融服务方案（授信业务调查报告）\", \"报告类型\": \"综合金融服务方案与授信业务调查报告\", \"客户概况\": \"申请人成立于1999年12月，民营股份有限公司，主营锡焊材料研发生产销售，产品涵盖焊锡膏、片、条、丝等。拥有高新技术企业、专精特新标识及20个有效专利（报告另称12个有效专利）。股权结构：控股股东占比70%-80%，其余为有限合伙持股。行业归属金属制品制造，下游覆盖半导体、汽车电子等高景气赛道。我行合作始于2005年，开立基本户，结算代发归集本行，活期年日均存款100万-500万，代发约22人/月。现有授信额度500万-1000万（知识产权质押），余额100万-500万。\", \"主营业务与经营\": \"主营业务为生产和销售锡焊材料及相关焊接产品，提供完整电子装联解决方案。上游供应商主要采购锡锭、锡粉、银等原材料，结算方式主要为款到发货；下游客户包括富士电机、比亚迪、日月新、中国中车等知名企业，账期一般2-3个月。以销定产模式，核心客户富士电机采用仕样书+订单模式长期稳定合作。具备技术壁垒和客户准入壁垒，产品验证周期1-2年，客户粘性强。2025年营收规模1000万-5000万，其中锡片占70%-80%。在手订单合计金额100万-500万左右。\", \"财务概况\": \"近四年营业收入均为1000万-5000万且逐年增长10%-20%；毛利率28%-35%间波动，盈利能力较强。2025年净利润为负（-11万元），主因原材料成本上升和研发投入增加（近年研发费用均在100万-500万）。资产负债率低（5%-20%），长短期偿债能力较强。经营活动净现金流2023年为负、2024年为正、2025年为负（-205万元），但销售回款能力强（收现比接近1倍）；应收账款周转天数40%-50天，存货周转天数30%-40天。总资产、净资产均处1000万-5000万区间。财务报表未经审计。\", \"授信方案\": \"本次申请为首贷，拟新增授信总额度500万-1000万（敞口同额），品种流动资金贷款，期限1年，利率2%-3%，用途为支付货款等日常经营周转。测算资金缺口合理，用信前需办妥担保质押手续。\", \"担保与还款\": \"担保方式为知识产权质押加法定代表人夫妇保证担保。质押物为一项发明专利（一种水洗低温无铅锡膏及其制备方法），评估价值1000万-5000万，质押率40%-50%。法人代表名下房产市值约1000万-5000万（无抵押按揭），个人信用良好，对外担保余额100万-500万。还款来源为企业自身经营性收入，预计可覆盖本笔授信。\", \"主要风险\": [\"下游第一大客户富士电机销售额占总营收60%-70%，存在较高客户集中风险；若订单减少将直接冲击收入和现金流\", \"2025年净利润为负（-11万元）且经营活动净现金流为负（-205万元），盈利能力和现金创造能力下滑，需关注持续改善情况\"], \"综合评价\": \"公司属专精特新科技型中小企业，在锡焊料细分领域具备技术和客户壁垒，已获头部客户认可，主业稳健增长；财务上负债水平极低，偿债能力较好，但近期利润转亏且经营现金流承压，主要受原材料涨价和加大研发影响；整体经营基础扎实，银企合作关系紧密，第一还款来源有一定保障，但需重点关注大客户依赖程度及盈利恢复趋势。\"}}, {\"report_id\": \"rpt_4bc9681732696f67f3b14bb7\", \"report_name\": \"思源电气集团综合授信调查报告\", \"report_type\": \"综合授信业务调查报告\", \"score\": 82.5, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"大型企业/大型企业（上海****开关有限公司前身？实际报告显示该主体为\\\"大型企业/大型企业\\\"），中型企业/小型企业（上海********），小型企业/小型企业（上海****科技有限公司）。集团整体按工信部标准应归为大型企业。\", \"similarity\": 0.7}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业-汽车零部件及配件制造（申请人之一上海********）；批发和零售业-机械设备、五金产品及电子产品批发；输配电及控制设备制造等。集团主业为输配电设备及其核心零部件的研发制造，所属行业涵盖制造业多个子类。\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业-汽车零部件及配件制造（申请人之一上海********）；批发和零售业-机械设备、五金产品及电子产品批发；输配电及控制设备制造等。集团主业为输配电设备及其核心零部件的研发制造，所属行业涵盖制造业多个子类。\"}, {\"name\": \"企业规模\", \"value\": \"大型企业/大型企业（上海****开关有限公司前身？实际报告显示该主体为\\\"大型企业/大型企业\\\"），中型企业/小型企业（上海********），小型企业/小型企业（上海****科技有限公司）。集团整体按工信部标准应归为大型企业。\"}, {\"name\": \"主营业务\", \"value\": \"集团主营输配电设备（高压开关、变压器、电容器等）的研发生产销售及海外EPC总包。本次四户分别从事：①汽车用12V锂电模组与超容模组产销；②动态无功补偿装置SVG、储能系统产销；③直流框架隔离开关、轨交断路器产销；④户用及工商业储能设备产销。\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"集团合并2025年末100万-500万元（区间）。各下属公司：上海********2026年3月末1万-5亿元；********2026年3月末10万-50亿元；上海****开关有限公司2026年3月末1万-5亿元；上海****科技有限公司2026年3月末1万-5亿元。\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"集团合并2025年末总负债无法直接获取，仅知资产负债率40%-50%，由总资产区间×资产负债率推算约40万-250万元。各下属公司负债合计可查：上海********2026年3月流动负债1万-5亿+非流动负债不详；********2026年3月流动负债10万-50亿；其余类似。\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"集团合并2025年度净利润10万-50万元。各下属公司2025年全年：上海******** -4,091万元；******** 100-500万元；上海****开关有限公司 -2,650万元；上海****科技有限公司 1,000-5,000万元。\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"集团合并2025年度经营活动净现金流10万-50万元。各主要子公司：********2025年经营净现金流-41,251万元；上海********2025年未单独披露但推测为负；其他两家因体量较小未详述。\"}, {\"name\": \"是否集团客户\", \"value\": \"是。本笔业务明确按照\\\"**电气集团\\\"进行统一授信管理，包含4家并表控股子公司，使用集团敞口额度并合并管控。\"}, {\"name\": \"是否科技型企业\", \"value\": \"是。上海********为国家高新技术企业、国家级专精特新小巨人企业；集团层面拥有国家企业技术中心、博士后科研工作站，持续高强度研发投入。\"}, {\"name\": \"所有制性质\", \"value\": \"民营/私人相对控股。实际控制人为董**及一致行动人陈**，合计持股29.13%（无质押）。下属公司分别为有限责任公司(自然人投资或控股)、有限责任公司(非自然人投资或控股的法人独)等，最终穿透仍属民营企业。\"}, {\"name\": \"授信金额\", \"value\": \"集团新增敞口额度由原1亿-5亿元增至5亿元以上。其中：上海********维持综合授信5000万-1亿元；********从1亿-5亿元增贷至5亿元以上；上海****开关有限公司维持流贷1000万-5000万元；上海****科技有限公司从1000万-5000万元增贷至1亿-5亿元。四户合计可提款授信额度5亿元以上。\"}, {\"name\": \"授信期限\", \"value\": \"1年。各品种均注明期限1年。\"}, {\"name\": \"授信品种\", \"value\": \"综合授信，包括流动资金贷款、银行承兑汇票、非融资性保函、供应链金融。\"}, {\"name\": \"担保方式\", \"value\": \"信用。全部采用免保证金信用方式。\"}, {\"name\": \"担保人\", \"value\": \"无。本笔业务为信用方式，不涉及保证人。\"}, {\"name\": \"担保物\", \"value\": \"无。抵质押物栏为空。\"}, {\"name\": \"贷款用途\", \"value\": \"用于采购原材料、支付工资等流动资金周转。其中上海********的部分贷款可用于归还母公司借款（母公司借款穿透用于我行存量贷款）。\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为企业销售收入。第二还款来源未明确提及，但因系信用担保无抵押物，依赖企业经营现金回流。\"}, {\"name\": \"申请性质\", \"value\": \"增贷。集团原有敞口额度1亿-5亿元，现申请增加至5亿元以上。\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否。报告首页勾选\\\"否\\\"。\"}], \"summary\": {\"报告名称\": \"思源电气集团综合授信调查报告\", \"报告类型\": \"综合授信业务调查报告\", \"客户概况\": \"申请人包括上海********、********（清能）、上海****开关有限公司、上海****科技有限公司共4户，均为上市公司思源电气的并表子公司。思源电气成立于1993年，2004年在深交所上市，主营输配电设备及储能系统，民营控股。各子公司在汽车电子电器、储能系统、低压开关等领域布局，整体属于制造业-汽车零部件/电气机械行业。报告未披露完整的企业规模、社保人数等基本信息。\", \"主营业务与经营\": \"主营业务涵盖：①思源汽车从事12V锂电产品生产销售；②清能从事SVG无功补偿装置及储能系统的研发生产和销售；③思源开关从事直流框架隔离开关、旁路开关等产品的研发和销售；④思源科技从事户用及小型工商业储能设备的出口销售。经营模式以销定产，下游客户包括车企、发电集团及海外经销商。\", \"财务概况\": \"集团合并2025年末总资产100万-500万元，资产负债率40%-50%，净利润10万-50万元，经营活动现金流5亿元以上。四家申请人均处于亏损或微利状态：思源汽车净资产为负(-4776万元)，营收2.37亿但持续亏损(净亏4091万)；清能营收26.48亿，微盈约100万-500万元；思源开关营收4760万，净亏2650万；思源科技营收1.68亿，盈利1000万-5000万。报告未提供完整的现金流量表和关键财务指标明细。\", \"授信方案\": \"本次为增贷，集团敞口额度由原1亿-5亿增加至5亿元以上。具体方案：①思源汽车综授5000万-1亿(维持)；②清能综授5亿元以上(含流贷、承兑、非融资性保函、供应链，由1亿-5亿增贷)；③思源开关流贷1000万-5000万(维持)；④思源科技流贷1亿-5亿(由1000万-5000万增贷)。期限均1年，担保方式信用，承兑保证金比例0。\", \"担保与还款\": \"本笔全部采用信用方式，无抵质押物或第三方保证。还款来源主要为各企业自身销售收入。集团层面货币资金充裕，上市公司思源电气可提供内部借款支持。\", \"主要风险\": [\"四家申请人中有三家持续亏损且净资产为负（思源汽车、思源开关、思源科技），对母公司资金依赖度高，若集团支持力度变化将影响偿债能力。\", \"清能公司储能业务虽高速增长但毛利率极低（25年仅1%-2%），经营性现金流大额为负（25年净流出41251万元），短期流动性承压。\", \"思源汽车经营历史较短且业绩波动大，原先的超容模组等传统业务萎缩后转型锂电，目前仍处大规模研发投入期，未来盈利能力存不确定性。\", \"思源科技的应收账款周转天数较长（138天）且存货周转慢（153天），叠加海外回款周期长，营运资金占用严重。\"], \"综合评价\": \"该集团在输配电领域技术积累深厚，核心子公司及新兴板块具有成长潜力，银行合作意愿较强。但本次涉及的四个主体多数尚处早期扩张阶段，财务状况偏弱，需依靠集团统筹支持和持续的信贷资源注入才能实现良性运转。\"}}, {\"report_id\": \"rpt_134a0e24019fbaea936c9c71\", \"report_name\": \"温州分行-制造业客户综合金融服务方案及授信调查报告\", \"report_type\": \"综合金融服务方案与授信业务调查报告（首贷）\", \"score\": 82.5, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"中型或大型（未明示小微/中型/大型；员工102人，营收5亿以上，总资产约6.13亿元）\", \"similarity\": 0.7}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业（聚氨酯树脂制造）\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业（聚氨酯树脂制造）\"}, {\"name\": \"企业规模\", \"value\": \"中型或大型（未明示小微/中型/大型；员工102人，营收5亿以上，总资产约6.13亿元）\"}, {\"name\": \"主营业务\", \"value\": \"主要从事研发、生产销售聚氨酯树脂等产品；“日胜”牌聚氨酯系列产品在同行中享有较高口碑。\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"约5亿-10亿元（2025年6月报表未经审计，区间值）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"约5000万-1亿元（2025年6月报表未经审计，区间值）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"1000万-5000万元（2025年6月报表未经审计，区间值）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（无现金流量表）\"}, {\"name\": \"是否集团客户\", \"value\": \"否（未被纳入本行集团统一授信体系，也无集团认定描述）\"}, {\"name\": \"是否科技型企业\", \"value\": \"是（曾获浙江省科技型中小企业称号，拥有23个实用专利，设有研发部门）\"}, {\"name\": \"所有制性质\", \"value\": \"民营（穿透后实际控制人为自然人******，占100%-150%）\"}, {\"name\": \"授信金额\", \"value\": \"本次申请授信额度不超过人民币1000万-5000万，敞口不超过人民币1000万-5000万\"}, {\"name\": \"授信期限\", \"value\": \"不长于1年\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款 + 资产池授信额度（可用于银承）\"}, {\"name\": \"担保方式\", \"value\": \"信用\"}, {\"name\": \"担保人\", \"value\": \"无（纯信用方式，无保证人）\"}, {\"name\": \"担保物\", \"value\": \"无（信用方式下无需抵押质押品）\"}, {\"name\": \"贷款用途\", \"value\": \"支付货款、代发工资等经营周转，不得流入股市期市等违规领域\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为申请人营业收入；第二还款来源为信用（即依靠自身信用履约，实质无外部保障）\"}, {\"name\": \"申请性质\", \"value\": \"首贷\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"温州分行-制造业客户综合金融服务方案及授信调查报告\", \"报告类型\": \"综合金融服务方案与授信业务调查报告（首贷）\", \"客户概况\": \"申请人成立于2002年，民营，主营聚氨酯树脂研发、生产销售，实控人穿透为自然人100%持股。属化工制造行业，具备危险化学品登记证等资质，曾获浙江省科技型中小企业称号。近三年营收连续下降但产量稳定，毛利率在10%-20%。资产负债率极低（9%-10%），无对外担保。\", \"主营业务与经营\": \"核心产品‘日胜’牌聚氨酯系列口碑良好，产销量国内同行前列。下游客户主要为制革企业，账期约3个月；上游采购MDI等原料需预付或月结。产能利用率高（2024年99.56%），产销率达100.05%，满负荷生产。\", \"财务概况\": \"报告未披露完整审计后财务报表，所有数据均未经审计。2024年末资产总额5亿以上，净资产5亿以上，货币资金5000万-1亿（含受限存款）。净利润1000万-5000万，经营现金流量净额报告未列明。应收账款周转天数130天，存货周转天数150天，均高于行业均值。无现金流量表。\", \"授信方案\": \"申请首贷，授信额度不超过1000万-5000万（敞口相同），期限1年，品种包括流动资金贷款和资产池授信额度（可用于银承，单笔不超6个月）。流贷利率不低于LPR-50BP（即2%-3%）。用途为支付货款、代发工资等经营周转。\", \"担保与还款\": \"本笔采用信用方式，无抵押或保证。第一还款来源为营业收入，第二还款来源为信用。\", \"主要风险\": [\"财报未经审计，财务指标真实性缺乏外部验证。\", \"近三年收入持续下滑（从6.13亿元降至5.49亿元），主要因降价竞争。\", \"应收款项周转天数（130天）和存货周转天数（150天）远超行业均值。\", \"征信历史存在短期借款关注类记录及承兑垫款，虽解释为疏忽但仍构成瑕疵。\"], \"综合评价\": \"该企业经营年限长、负债水平极低、产能饱和且客户关系稳定，整体偿债能力较强。但面临行业竞争加剧导致收入下滑、营运效率偏低等问题，且关键财务信息未经审计。本次以纯信用方式介入首贷，风险缓释措施有限。\"}}, {\"report_id\": \"rpt_f47eabb866e4c93ef684bc84\", \"report_name\": \"温州分行-彭晓影-信息系统集成服务-综合金融服务方案（授信申请）\", \"report_type\": \"综合金融服务方案（含送审意见书）\", \"score\": 82.5, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"无法直接认定为大中小微型，依据从业人员98人及营收区间推算应为中型或小型，但报告未明示规模类型\", \"similarity\": 0.7}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"计算机、通信和其他电子设备制造业；主营业务为信息系统集成服务\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"计算机、通信和其他电子设备制造业；主营业务为信息系统集成服务\"}, {\"name\": \"企业规模\", \"value\": \"无法直接认定为大中小微型，依据从业人员98人及营收区间推算应为中型或小型，但报告未明示规模类型\"}, {\"name\": \"主营业务\", \"value\": \"信息系统集成服务，具体包括某重点项目业务、某重点项目业务、某重点项目业务、通信设备销售业务\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"截至2026年3月末公司总资产1亿-5亿元\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"截至2026年3月末公司总负债1亿-5亿元\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"2026年一季度净利润率为-8%至-9%，净利润金额不可提取\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（全文无经营活动产生的现金流量净额数据）\"}, {\"name\": \"是否集团客户\", \"value\": \"否（不涉及集团统一授信）\"}, {\"name\": \"是否科技型企业\", \"value\": \"是（国家级高新技术企业、省级专精特新中小企业、科技型中小企业）\"}, {\"name\": \"所有制性质\", \"value\": \"集体所有制（实控人为瑞安市集体邮电联营管理站，持股90%-100%）\"}, {\"name\": \"授信金额\", \"value\": \"综合授信额度不超过人民币1000万-5000万元\"}, {\"name\": \"授信期限\", \"value\": \"1年\"}, {\"name\": \"授信品种\", \"value\": \"流动资金贷款、国内信用证（免保证金）\"}, {\"name\": \"担保方式\", \"value\": \"信用\"}, {\"name\": \"担保人\", \"value\": \"无（本次授信为信用方式，不设置担保人）\"}, {\"name\": \"担保物\", \"value\": \"无（本次授信为信用方式，不涉及抵押或质押物）\"}, {\"name\": \"贷款用途\", \"value\": \"原材料采购、技术支持服务、支付工资等日常经营周转、归还他行贷款\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为申请人营业收入；第二还款来源为信用\"}, {\"name\": \"申请性质\", \"value\": \"首次申请\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"温州分行-彭晓影-信息系统集成服务-综合金融服务方案（授信申请）\", \"报告类型\": \"综合金融服务方案（含送审意见书）\", \"客户概况\": \"******成立于2003年，为科技型中小企业、国家级高新技术企业，属于计算机通信和其他电子设备制造业。注册资金5000万至1亿，实缴资本1000万至5000万。股权结构为瑞安市集体邮电联营管理站持股98%，实控人为该管理站（集体所有制）。员工98人，研发人员30人。公司扎根瑞安，辐射温州及浙南区域，是本地综合型通信智能化服务商。\", \"主营业务与经营\": \"主营业务包括某重点项目业务、某重点项目业务、某重点项目业务和通信设备销售。经营模式以招投标获取政企订单为主，客户涵盖电信运营商、政府等。2025年营收1亿至5亿，近三年复合增长率超20%。截至2026年6月在手订单超1亿至5亿。\", \"财务概况\": \"截至2026年3月末总资产1亿至5亿，资产负债率70%至80%。2025年营业收入1亿至5亿，净利润率2.61%；但2026年第一季度净利润率为负（-8%至-9%），主因项目进度付款导致前期投入大且年终奖在一季度发放。现金流方面：货币资金/上年三费=1.43；经营性流水可覆盖报表收入。报告未披露经营活动净现金流具体数据。\", \"授信方案\": \"申请综合授信额度不超过人民币1000万至5000万，期限1年，品种为流动资金贷款和国内信用证（免保证金），首次申请。用途包括原材料采购、技术支持服务、支付工资及归还他行贷款。\", \"担保与还款\": \"担保方式为信用。第一还款来源为申请人营业收入；第二还款来源同信用保证。无其他担保措施或抵质押物。\", \"主要风险\": [\"财务风险：项目回款周期长，应收账款较高（占总资产比重较大），2026年一季度出现亏损，对流动性形成压力。\", \"担保偏弱：本次授信仅凭信用，无抵押或第三方保证，银行风险缓释不足。\", \"信息缺口：报告中多项关键数据（如注册资本、法定代表人姓名、实控人从业经历、家庭资产负债等）被脱敏处理或填写“/”，无法核实完整信息。\"], \"综合评价\": \"该公司为国有背景的科技型企业，在本地系统集成领域具备资质和技术优势，近年营收增长较快、在手订单充足。但存在应收账款高企、盈利能力波动、担保方式单一等问题，且报告部分核心信息披露不充分。整体经营稳健，需关注其现金流管理和回款情况。\"}}, {\"report_id\": \"rpt_f9d31a50b9a7e924179f2919\", \"report_name\": \"苏州分行-322127俞浥尘-制造-001授信调查报告（原额度续借）\", \"report_type\": \"授信业务调查报告（制造型企业）\", \"score\": 82.5, \"recommendation_reason\": \"满足全部已确认筛选条件：企业规模、行业分类。\", \"matched_tags\": [{\"name\": \"企业规模\", \"query_value\": \"小微企业\", \"report_value\": \"大型或中型，员工210人，营收1亿-5亿元/年，总资产1亿-5亿元。无法直接判定为小微或明确的大型/中型。\", \"similarity\": 0.7}, {\"name\": \"行业分类\", \"query_value\": \"制造业\", \"report_value\": \"制造业-汽车制造业-汽车零部件及配件制造-汽车零部件及配件制造\", \"similarity\": 0.9}], \"unmatched_tags\": [], \"missing_tags\": [], \"report_tags\": [{\"name\": \"行业分类\", \"value\": \"制造业-汽车制造业-汽车零部件及配件制造-汽车零部件及配件制造\"}, {\"name\": \"企业规模\", \"value\": \"大型或中型，员工210人，营收1亿-5亿元/年，总资产1亿-5亿元。无法直接判定为小微或明确的大型/中型。\"}, {\"name\": \"主营业务\", \"value\": \"研发机电技术、汽车零部件及相关技术，设计模具；生产汽车用锁具、车门把手、开关、电子设备系统等；销售公司自主产品并提供技术服务；兼营原材料批发。主要产品包括车辆电器开关装置、控制系统装置和电子电控装置。\"}, {\"name\": \"最新一期财报总资产\", \"value\": \"人民币1亿-5亿元（截至2025年10月末）\"}, {\"name\": \"最新一期财报总负债\", \"value\": \"人民币1亿-5亿元（截至2025年10月末）\"}, {\"name\": \"最新一期财报净利润\", \"value\": \"人民币500万-1000万元（截至2025年10月末）\"}, {\"name\": \"最新一期经营性净现金流\", \"value\": \"不可提取（全文未披露经营活动产生的现金流量净额数据）\"}, {\"name\": \"是否集团客户\", \"value\": \"否\"}, {\"name\": \"是否科技型企业\", \"value\": \"是（拥有多项专利及软件著作权，研发人员45名占21%，且与国家高新技术企业特征相符）\"}, {\"name\": \"所有制性质\", \"value\": \"外商控股有限责任公司（60%-70%外商控股+35%央企子公司控股），穿透至实际控制人为株式会社摩贝斯电子（韩资）和中国贵州航空工业集团（国企）混合。\"}, {\"name\": \"授信金额\", \"value\": \"综合授信总额人民币1亿-5亿元，敞口1亿-5亿元（中期流贷敞口1亿-5亿元，研发贷敞口不超过1000万-5000万元，出口押汇敞口不超过人民币1000万-5000万元，衍生品免保证金不超过100万-500万元）。\"}, {\"name\": \"授信期限\", \"value\": \"3年\"}, {\"name\": \"授信品种\", \"value\": \"中期流动资金贷款、研发贷、衍生品免保证金、出口押汇\"}, {\"name\": \"担保方式\", \"value\": \"抵押、保证\"}, {\"name\": \"担保人\", \"value\": \"不可提取（全文未列出承担法律保证责任的自然人、法人或担保机构的具体信息）\"}, {\"name\": \"担保物\", \"value\": \"（1）位于苏州工业园区启月街288号紫金东方商务广场1商幢2-807/808/809/810室的四套写字楼房产，建筑面积303.11㎡、169.65㎡、174.24㎡、105.06㎡；（2）位于苏州浒墅关经济技术开发区嵩山路善兴路185号的工业厂房，建筑面积15266.43㎡，土地面积33376㎡。评估价值总计5000万-1亿元。\"}, {\"name\": \"贷款用途\", \"value\": \"用于企业日常经营周转\"}, {\"name\": \"还款来源\", \"value\": \"第一还款来源为公司经营收入（近三年主营业务收入稳定增长）；第二还款来源为抵押物的处置变现。\"}, {\"name\": \"申请性质\", \"value\": \"原额度续借\"}, {\"name\": \"是否我行关联企业\", \"value\": \"否\"}], \"summary\": {\"报告名称\": \"苏州分行-322127俞浥尘-制造-001授信调查报告（原额度续借）\", \"报告类型\": \"授信业务调查报告（制造型企业）\", \"客户概况\": \"申请人******成立于2003年，注册资本500万-1000万美元，外商控股60%-70%，央企子公司持股35%，主营汽车用组合开关、电子控制系统等零部件及配件制造。信用等级A-。\", \"主营业务与经营\": \"主营业务为乘用车电器开关装置、车辆控制系统和电子电控装置的研发生产与销售，以销定产模式，主要客户包括北京现代、起亚、广汽埃安等主机厂，产品国内市场份额约20%。近年逐渐转向国内市场，外销占比降至4%-5%。拥有140余项自主专利并可低价借用母公司500多项专利。\", \"财务概况\": \"2022至2024年营业收入持续增长，分别为1亿-5亿、1亿-5亿和1亿-5亿；净利润由2023年的亏损扭转为2024年盈利500万-1000万元并延续向好趋势。2025年10月末资产合计1亿-5亿元，流动比率100%-150%、速动比率80%-90%；净资产借款率升至100%-150%，短期偿债指标处于安全区间。现金流分析报告未披露详细数据。\", \"授信方案\": \"本次申请性质为原额度续借，拟增加授信1000万-5000万元，总敞口上升至人民币1亿-5亿元，期限3年，品种涵盖中期流动资金贷款、研发贷、衍生品免保证金及出口押汇，利率2%-3%，资金用于日常经营周转。\", \"担保与还款\": \"担保方式为抵押加保证，抵押物为一处工业厂房土地（面积15266.43㎡/33376㎡）及四套写字楼房产，评估总值5000万-1亿元。第一还款来源为企业主营业务收入覆盖流贷本息，第二还款来源为处置抵押物的变现保障。\", \"主要风险\": [\"公司存货账面余额持续高位且占流动资产比例较大，若市场需求或价格大幅下跌可能引发跌价风险。\", \"应收账款随营收扩张而显著增长（较2022年末增151.6%），账期有所延长，需关注回款质量。\", \"对外部股东存在固定收益支付义务，具体金额视经营情况而定，目前尚欠贵州华阳1000万-5000万元待付。\"], \"综合评价\": \"该企业成立逾二十年，股权结构中外资主导兼有央企背景；近年来营收稳步扩大、成功实现扭亏，但盈利能力仍低于行业均值；财务杠杆因主动融资支持扩张而升高，整体偿债能力稳健；抵押物区位良好且价值充足，还款来源具备一定保障；报告中部分关键信息如现金流量表、实收资本明细等未完整披露。\"}}], \"statistic\": null, \"answer\": null}','filter','2026-08-17 07:07:48');
