CREATE TABLE `sessions` (
  `session_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'legacy',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '新会话',
  `feature` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'recommendation',
  `active_intent` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'recommendation',
  `skipped_tags_json` varchar(2048) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '[]',
  `clarification_count` int NOT NULL DEFAULT '0',
  `refinement_count` int NOT NULL DEFAULT '0',
